        "没有订阅，没有广告，没有追踪。Mac Sai 是我和几位志愿者在业余时间做的。如果它帮你省下了买清理软件的钱，请我喝杯咖啡，让它对所有人继续免费。": "Sem assinatura, anúncios ou rastreamento. Desenvolvo o Mac Sai à noite e nos fins de semana com alguns voluntários. Se ele evitou que você pagasse por um aplicativo de limpeza, um café ajuda a mantê-lo gratuito para todos.",
