        "运行 docker system prune，删除未使用的镜像、已停止的容器、未使用的网络和构建缓存。此操作不可撤销（不会进入废纸篓）。正在运行的容器、使用中的镜像和命名卷不受影响，磁盘映像 Docker.raw 也不会被直接删除。": "Executa docker system prune para remover imagens sem uso, contêineres parados, redes sem uso e cache de compilação. É irreversível: nada vai para o Lixo. Contêineres em execução, imagens em uso e volumes nomeados são preservados. A imagem de disco Docker.raw nunca é apagada diretamente.",
