        "逐字节完全相同的副本。每个需要的文件请至少保留一份。": "Cópias idênticas byte por byte. Mantenha pelo menos uma cópia de cada arquivo necessário.",
        "通常没有可见影响——这些脚本与 macOS 夜间自动运行的维护脚本相同。": "Normalmente nenhum efeito visível: são os mesmos scripts que o macOS executa sozinho durante a noite.",
