        "清理权限": "Permissões de limpeza",
        "允许 Mac Sai 扫描邮件、浏览器数据和其他受保护的文件夹。在系统设置中添加 Mac Sai 并开启权限，然后重新启动应用并重新扫描。": "Permite que o Mac Sai verifique o Mail, os dados dos navegadores e outras pastas protegidas. Adicione o Mac Sai e ative o acesso nos Ajustes do Sistema, depois reinicie o aplicativo e verifique novamente.",
        "打开完全磁盘访问设置": "Abrir ajustes de Acesso Total ao Disco",
        "管理员确认": "Autorização do administrador",
        "移动受保护的项目时，macOS 可能仍会要求密码或触控 ID。完全磁盘访问权限不能代替管理员确认。Mac Sai 不保存您的密码，也不能提前批准所有操作。": "O macOS ainda pode pedir uma senha ou o Touch ID ao mover itens protegidos. O Acesso Total ao Disco não substitui a autorização do administrador. O Mac Sai não salva sua senha e não pode autorizar todas as operações com antecedência.",
        "批量移到废纸篓": "Mover para o Lixo em lotes",
        "清理会将选中的项目分组交给 macOS，减少逐项请求。系统决定是否需要再次确认。取消后，当前组会先完成；已移动的项目仍会显示在清理历史中。": "A limpeza envia os itens selecionados ao macOS em lotes para reduzir as solicitações individuais. O sistema decide quando é necessária uma nova autorização. Ao cancelar, o lote atual é concluído primeiro; os itens já movidos continuam no histórico de limpeza.",
        "权限": "Permissões",
        "另一项清理仍在进行中。": "Outra limpeza ainda está em andamento.",
        "准备清理时文件已更改，请重新扫描。": "O item mudou enquanto a limpeza era preparada. Verifique novamente.",
        "无法确认项目在废纸篓中的位置，请检查访达。": "Não foi possível confirmar a localização do item no Lixo. Verifique no Finder.",
        "macOS 未将此项目移到废纸篓。请检查权限并重新扫描。": "O macOS não moveu este item para o Lixo. Verifique as permissões e faça uma nova verificação.",
        "符号链接改变了清理路径。请在访达中检查。": "Um link simbólico alterou o caminho da limpeza. Confira no Finder.",
        "符号链接已跳过。": "Link simbólico ignorado.",
        "取消后会先完成当前一组。": "Ao cancelar, o lote atual é concluído primeiro.",
        "清理已停止": "Limpeza interrompida",
        "已处理": "processados",
        "选中的文件夹与其内容计为一项。已经消失的文件会被跳过。": "As pastas selecionadas contam como um único item junto com seu conteúdo. Arquivos que já não existem são ignorados.",
        "部分项目未能清理": "Não foi possível limpar alguns itens",
        "以上仅显示已完成的操作。移到废纸篓的项目可从清理历史恢复。请重新扫描以查看剩余或重新生成的文件。": "Acima aparecem apenas as operações concluídas. Os itens movidos para o Lixo podem ser restaurados pelo histórico de limpeza. Verifique novamente para revisar os arquivos restantes ou recriados.",
        "请逐项检查并选择可能的威胁和社区报告的文件。此复选框只能取消该类别中已选中的项目。": "Revise e selecione individualmente as possíveis ameaças e os arquivos relatados pela comunidade. Esta caixa só pode desmarcar os itens selecionados nesta categoria.",
        "全选": "Selecionar tudo",
        "取消全选": "Desmarcar tudo",
        "选择安全项目": "Selecionar itens seguros",
        "选择所有允许自动勾选的项目。需要手动检查的类别和可能的威胁保持不选。": "Seleciona todos os itens que podem ser marcados automaticamente. As categorias de revisão manual e as possíveis ameaças continuam desmarcadas.",
        "仅保留安全的临时文件、缓存、日志和残留文件。不选择个人数据、废纸篓或应用修改。": "Mantém selecionados apenas arquivos temporários, caches, logs e restos seguros. Não inclui dados pessoais, Lixo nem alterações em aplicativos.",
        "选中的文件会移到废纸篓，如有需要仍可恢复。": "Os arquivos selecionados serão movidos para o Lixo para que você possa recuperá-los, se necessário.",
        "废纸篓中选中的项目将永久删除，无法恢复。": "Os itens selecionados que já estão no Lixo serão apagados permanentemente e não poderão ser restaurados.",
        "应用中未使用的架构将被移除。恢复可能需要重新安装应用。": "As arquiteturas sem uso serão removidas dos aplicativos. Para restaurá-las, pode ser necessário reinstalar os aplicativos.",
        "无法开启登录时启动：{message}": "Não foi possível ativar a abertura ao iniciar sessão: {message}",
        "无法关闭登录时启动：{message}": "Não foi possível desativar a abertura ao iniciar sessão: {message}",
        "提醒": "Alertas",
        "内存压力提醒": "Alerta de pressão de memória",
        "内存压力持续偏高时通知你。": "Avisa você quando a pressão de memória continua alta.",
        "交换空间提醒": "Alerta de uso de swap",
        "交换空间超过所选大小时通知一次，降到明显低于该值后才会再次提醒。": "Avisa uma vez quando o swap passa do tamanho escolhido e só avisa de novo depois que ele cair bem abaixo desse valor.",
        "不提醒": "Desativado",
        "提醒由菜单栏小组件发送，需要保持开启。": "Os alertas são enviados pelo widget da barra de menus, que precisa ficar ativado.",
        "交换空间 {size}": "Swap {size}",
        "交换空间使用过高": "Uso de swap alto",
        "你的 Mac 正在使用 {used} 交换空间，超过了你设置的 {limit} 提醒值。退出不用的应用可以减轻内存压力。": "Seu Mac está usando {used} de swap, acima do seu alerta de {limit}. Encerrar os aplicativos que você não está usando alivia a pressão de memória.",
        "Base 资源、Mac Sai 的界面语言以及你的 Mac 在“语言与地区”中设置的语言会始终保留。已勾选的语言会保留；未勾选的语言文件可由“系统垃圾”移除。": "Os recursos Base, os idiomas da interface do Mac Sai e os idiomas definidos em Idioma e Região no seu Mac são sempre mantidos. Os idiomas marcados são preservados; os arquivos de idiomas desmarcados podem ser removidos por Arquivos desnecessários.",
        "可能的威胁": "Possíveis ameaças",
        "Apple XProtect 特征：{name}": "Assinatura do Apple XProtect: {name}",
        "在 Apple 的 Safari 扩展黑名单中：{name}": "Na lista de bloqueio da Apple para extensões do Safari: {name}",
        "名称与已知家族相符：{name}": "O nome corresponde a uma família conhecida: {name}",
        "启动代理会运行“{name}”": "O agente de inicialização executa “{name}”",
        "标记原因": "Por que foram sinalizados",
        "没有可直接移除的威胁": "Nenhuma ameaça que o Mac Sai possa remover",
        "已发现，但需要管理员才能移除": "Encontrado, mas a remoção exige um administrador",
        "这些项目位于 Mac Sai 无法修改的系统文件夹中。请在 Finder 中显示每一项，然后输入管理员密码将其移到废纸篓。": "Estes itens estão em pastas do sistema que o Mac Sai não pode alterar. Mostre cada um no Finder e mova-o para o Lixo por lá com sua senha de administrador.",
        "Apple XProtect {version}：{count} 个哈希值，{blocked} 个被屏蔽的 Safari 扩展": "Apple XProtect {version}: {count} hashes, {blocked} extensões do Safari bloqueadas",
        "未在这台 Mac 上找到 Apple XProtect 数据": "Dados do Apple XProtect não encontrados neste Mac",
        "在黑名单上或由社区报告、但也可能是你有意安装的软件的项目。": "Correspondências com uma lista de bloqueio ou relatadas pela comunidade que também podem ser software instalado de propósito.",
        "不会预先勾选。黑名单可能也涵盖曾经正当的软件的旧版本，社区报告也未经厂商确认，删除前请逐个核对。": "Nada é pré-selecionado. Uma lista de bloqueio também pode incluir versões antigas de software que já foi legítimo, e os relatos da comunidade não são confirmados por nenhum fabricante, então confira cada item antes de removê-lo.",
        "正在比对 XProtect 和 MalwareBazaar 哈希值...": "Comparando hashes do XProtect e do MalwareBazaar...",
        "已报告至 MalwareBazaar：{name}": "Relatado ao MalwareBazaar: {name}",
        "MalwareBazaar：未启用（可在设置中添加免费的 Auth-Key）": "MalwareBazaar: desativado (adicione uma Auth-Key gratuita nos Ajustes)",
        "MalwareBazaar：{count} 个哈希值，更新于 {date}": "MalwareBazaar: {count} hashes, atualizado em {date}",
        "恶意软件数据库": "Bancos de dados de malware",
        "版本 {version}：{hashes} 个哈希值，{blocked} 个被屏蔽的 Safari 扩展。由 macOS 自动更新。": "Versão {version}: {hashes} hashes, {blocked} extensões do Safari bloqueadas. O macOS mantém os dados atualizados.",
        "可选。按下“立即更新”时，使用你免费的 abuse.ch Auth-Key 下载最近报告的 macOS 恶意软件样本哈希值。每次请求只发送你的 Auth-Key 和查询内容，绝不发送文件哈希值或路径。如果某个哈希与已签名的文件匹配，macOS 会向 Apple 查询其签名证书是否已被吊销。匹配项不会预先勾选。": "Opcional. Ao clicar em Atualizar agora, baixa os hashes de amostras de malware para macOS relatadas recentemente usando sua Auth-Key gratuita da abuse.ch. Cada solicitação envia apenas sua Auth-Key e a consulta, nunca hashes ou caminhos de arquivos. Se um hash corresponder a um arquivo assinado, o macOS pergunta à Apple se o certificado de assinatura foi revogado. As correspondências nunca são pré-selecionadas.",
        "abuse.ch Auth-Key": "Auth-Key da abuse.ch",
        "保存密钥": "Salvar chave",
        "移除密钥和哈希值": "Remover chave e hashes",
        "立即更新": "Atualizar agora",
        "获取免费密钥": "Obter uma chave gratuita",
        "正在更新…": "Atualizando…",
