        "无法移除密钥或哈希值。": "Não foi possível remover a chave ou os hashes.",
        "Auth-Key 被拒绝。请在 auth.abuse.ch 检查。": "A Auth-Key foi recusada. Verifique-a em auth.abuse.ch.",
        "尚未下载哈希值。": "Nenhum hash baixado ainda.",
        "已更新：新增 {added} 个，共 {total} 个哈希值。": "Atualizado: {added} novos, {total} hashes no total.",
        "部分查询失败：{list}": "Algumas consultas falharam: {list}",
        "更新失败：{list}": "Falha na atualização: {list}",
        "无法保存下载的哈希列表。": "Não foi possível salvar a lista de hashes baixada.",
        "服务器要求重定向，已拒绝": "o servidor pediu um redirecionamento, que foi recusado",
