        "Mac Sai 无法确认此扩展的文件夹可以安全移除，因此未删除任何内容。": "Mac Sai가 이 확장 프로그램의 폴더를 안전하게 제거할 수 있는지 확인할 수 없어 아무것도 삭제하지 않았습니다.",
