        "Safari 扩展不能在本应用内开启、关闭或删除，以免破坏宿主应用的签名。请在 Safari 设置中管理它们。": "여기에서는 Safari 확장 프로그램을 켜거나 끄거나 삭제할 수 없습니다. 그러면 호스트 앱의 서명이 손상될 수 있습니다. Safari 설정에서 관리하세요.",
