        "macOS 诊断日志。": "macOS 진단 로그입니다.",
        "macOS 诊断日志。仅在排查过去的问题时有用；macOS 会继续写入新日志。": "macOS 진단 로그입니다. 과거 문제를 조사할 때만 유용하며 macOS는 계속 새 로그를 작성합니다.",
        "npm、Cargo、pip、Homebrew、Gradle 的可重建缓存。": "npm, Cargo, pip, Homebrew 및 Gradle에서 재생성 가능한 캐시입니다.",
        "{browser} 正在运行，因此未删除任何内容。请在 {browser} 的地址栏中打开 {url} 来移除此扩展。": "{browser} 앱이 열려 있어 아무것도 삭제하지 않았습니다. 주소 표시줄에서 {url}을(를) 열어 {browser}에서 확장 프로그램을 제거하세요.",
        "~/Library/Logs/MacClean/operations.log — 30 天后自动清理": "~/Library/Logs/MacClean/operations.log: 30일 후 자동으로 정리됨",
        "“邮件”应用的搜索索引会从头重建。重建完成前，邮件搜索和未读数可能不准确（大型邮箱通常需 10–30 分钟）。": "Mail 앱의 검색 색인이 처음부터 다시 작성됩니다. 재구축이 완료될 때까지 메일 검색 및 읽지 않은 메일 수가 정확하지 않을 수 있습니다(대용량 사서함은 보통 10~30분).",
        "一切就绪！": "모든 준비가 완료되었습니다!",
        "一键清理": "원클릭 정리",
        "上一级": "상위 폴더",
        "上次打开": "마지막으로 연 날짜",
        "下一步": "다음",
        "下载": "다운로드",
        "下载和构建缓存。npm、Cargo、pip、Homebrew 和 Gradle 会在下次安装或构建时重新下载所需内容。": "다운로드 및 빌드 캐시입니다. npm, Cargo, pip, Homebrew 및 Gradle은 다음 설치나 빌드 때 필요한 파일을 다시 다운로드합니다.",
        "下载文件夹中超过一周的磁盘映像，通常是已运行过的安装程序。如需要可重新下载。": "다운로드 폴더에 있는 일주일 이상 된 디스크 이미지로, 보통 이미 실행한 설치 프로그램입니다. 필요하면 다시 다운로드할 수 있습니다.",
        "不会自动勾选。": "아무것도 자동으로 선택되지 않습니다.",
        "不再提示": "다시 묻지 않기",
        "不可写": "쓸 수 없음",
        "不可用的模拟器": "사용할 수 없는 시뮬레이터",
        "不能排除整个 /Volumes。": "/Volumes 전체를 제외할 수 없습니다.",
        "不能排除整个主目录。": "전체 홈 폴더를 제외할 수는 없습니다.",
        "主题": "테마",
        "仅临时和缓存文件夹。Claude 和 Codex 会按需重新生成；绝不包含历史、记忆和会话。": "임시 및 캐시 폴더만 해당됩니다. Claude와 Codex가 필요할 때 다시 생성하며, 기록, 메모리 및 세션은 절대 포함되지 않습니다.",
        "仅显示图标": "아이콘만",
        "仅显示错误": "오류만",
        "仅移除 macOS 已标记可清理的 Time Machine 本地快照；不会删除你主动需要的内容。": "macOS가 이미 정리 대상으로 표시한 Time Machine 로컬 스냅샷만 제거합니다. 사용자에게 필요한 항목은 삭제되지 않습니다.",
        "仅编辑器缓存。Cursor 和 Antigravity 下次启动时会重新生成；你的设置和扩展不受影响。": "편집기 캐시만 해당됩니다. Cursor와 Antigravity가 다음 실행 시 다시 생성하며, 설정과 확장 프로그램은 영향을 받지 않습니다.",
        "仍要运行": "계속 실행",
        "从大到小": "큰 파일 먼저",
        "从小到大": "작은 파일 먼저",
        "从应用中移除这台 Mac 无法运行的 CPU 代码。会直接修改应用；只有重新安装才能撤销。": "앱에서 이 Mac이 실행할 수 없는 CPU 코드를 삭제합니다. 설치된 앱을 직접 변경하므로 다시 설치해야만 되돌릴 수 있습니다.",
        "代码": "코드",
        "代码编辑器的缓存（Cursor、Antigravity 等）。": "Cursor 및 Antigravity와 같은 코드 편집기의 캐시입니다.",
        "代码项目中的依赖和构建文件夹。": "코드 프로젝트의 종속성 및 빌드 폴더입니다.",
        "以后再说": "나중에",
        "以已不再安装的应用命名的支持文件夹（每行的名称就是该应用的 ID）。以后重新安装该应用会从头开始。": "더 이상 설치되어 있지 않은 앱의 지원 폴더입니다. 각 행의 이름은 해당 앱의 ID입니다. 나중에 앱을 다시 설치하면 초기 상태로 시작합니다.",
        "以开源方式让你的 Mac 保持干净、快速和安全。": "Mac을 깨끗하고 빠르며 안전하게 유지하는 오픈 소스 방법입니다.",
        "优化": "최적화",
        "优化你的 Mac": "Mac 최적화",
        "会产生几分钟磁盘活动。该操作为只读，无论结果如何都不会更改磁盘内容。": "몇 분 동안 디스크 작업이 발생합니다. 읽기 전용 작업이므로 결과와 관계없이 디스크 내용은 변경되지 않습니다.",
        "会删除本地 Time Machine 快照以释放空间。远程或备份盘上的快照不受影响，你仍可从 Time Machine 备份恢复。": "디스크 공간을 확보하기 위해 로컬 Time Machine 스냅샷을 삭제합니다. 원격 또는 백업 드라이브의 스냅샷은 영향을 받지 않으며, Time Machine 백업에서 계속 복원할 수 있습니다.",
        "会自动重建": "자동으로 다시 생성됨",
        "你不使用的语言翻译。移除会修改应用包；如需恢复请重新安装应用。": "사용하지 않는 언어의 번역입니다. 제거하면 앱 번들이 변경되며, 복원하려면 앱을 다시 설치하세요.",
        "你的 Mac 很干净！": "Mac이 깨끗해졌습니다!",
        "你的浏览历史和跟踪数据。清理后无法恢复；Cookie 和登录会话会保留。": "방문 기록 및 추적 데이터입니다. 정리 후에는 복원할 수 없으며, 쿠키와 로그인 세션은 유지됩니다.",
        "你自己的文件，仅按大小挑选。这里没有任何东西天生就是垃圾；请逐个检查。": "크기만으로 선별한 사용자의 파일입니다. 여기 있는 항목은 원래 불필요한 파일이 아니므로 하나씩 확인하세요.",
        "你选择的项目已在废纸篓中——需要时可以恢复。若要彻底删除，请打开“废纸篓”模块并清空。": "선택한 항목은 휴지통에 있으므로 필요하면 복구할 수 있습니다. 완전히 삭제하려면 휴지통 모듈을 열고 비우세요.",
        "使用渐进式 SHA-256 哈希检测\n查找重复文件": "단계적 SHA-256 해시 검사로\n중복 파일을 찾습니다",
        "保留": "유지",
        "修复 Finder 的文件类型与应用打开方式数据库": "Finder의 파일 유형과 앱 연결 데이터베이스 복구",
