        "匹配已知恶意软件特征。如果它属于你有意安装的软件，请先检查路径。": "알려진 악성코드 서명과 일치합니다. 의도적으로 설치한 소프트웨어라면 먼저 경로를 확인하세요.",
        "占用空间最多的文件。": "가장 많은 공간을 차지하는 파일입니다.",
        "占用资源": "리소스 사용 현황",
        "卷": "볼륨",
        "卷可能保存着数据库等数据，Mac Sai 不会清理它们。如需删除，请使用 Docker Desktop 或 Docker 命令行。": "볼륨에는 데이터베이스 등 영구 데이터가 있을 수 있으므로 Mac Sai는 볼륨을 정리하지 않습니다. 제거하려면 Docker Desktop 또는 docker 명령을 사용하세요.",
        "卸载": "제거",
