        "合并": "통합",
        "合并所选副本？": "선택한 사본을 통합하시겠습니까?",
        "同一文件的相同副本。": "동일한 파일의 동일한 복사본입니다.",
        "名称与已知广告软件家族相符。这只是提示，并非确认。": "이름이 알려진 애드웨어 계열과 일치합니다. 확인된 탐지가 아니라 참고용 표시일 뿐입니다.",
