        "在 Chrome、Brave、Edge、Arc、Firefox 或 Safari 中未找到扩展": "Chrome, Brave, Edge, Arc, Firefox 또는 Safari에서 확장 프로그램을 찾을 수 없습니다",
        "在 Finder 中显示": "Finder에서 보기",
        "在 Finder 中查看配置文件": "Finder에서 구성 보기",
        "在 GitHub 上浏览代码库": "GitHub에서 코드베이스 찾아보기",
        "在屏幕顶部实时显示 CPU、内存、磁盘、电池和网络状态。点击可展开浮窗。": "메뉴 막대에 CPU, 메모리, 디스크, 배터리 및 네트워크 상태를 실시간으로 표시합니다. 클릭하면 팝오버가 열립니다.",
        "在监控位置检测到新的可执行文件": "모니터링 중인 위치에서 새 실행 파일이 감지되었습니다",
