        "大小": "크기",
        "大文件": "대용량 파일",
        "大文件与旧文件": "크고 오래된 파일",
        "失效的登录项": "유효하지 않은 로그인 항목",
        "失败或孤立下载留下的文件。": "실패했거나 중단된 다운로드가 남긴 파일입니다.",
        "失败或被放弃的下载留下的文件。如仍需要，请重新下载。": "실패했거나 중단된 다운로드가 남긴 파일입니다. 아직 필요하면 파일을 다시 다운로드하세요.",
        "好": "확인",
        "如果 {browser} 已关闭，扩展文件夹会移到废纸篓。如果它正在运行，则不会删除任何内容，并会告诉你在哪里移除。如果你开启了 {browser} 同步，它可能会重新安装此扩展。": "{browser} 앱이 닫혀 있으면 확장 프로그램 폴더를 휴지통으로 이동합니다. 열려 있으면 아무것도 삭제하지 않고 제거 방법을 안내합니다. {browser} 동기화를 사용 중이면 확장 프로그램이 다시 설치될 수 있습니다.",
        "存储空间严重不足": "저장 공간이 매우 부족함",
        "安全擦除": "보안 삭제",
        "安全擦除文件，使其无法恢复": "파일을 복구할 수 없도록 안전하게 삭제",
        "安装包": "설치 프로그램",
        "完全磁盘访问权限": "전체 디스크 접근 권한",
        "完成": "완료",
        "完整日志：~/Library/Logs/MacClean/operations.log": "전체 로그: ~/Library/Logs/MacClean/operations.log",
        "实时系统状态": "실시간 시스템 상태",
        "容器": "컨테이너",
        "将当前内容复制到剪贴板，可粘贴到 GitHub issue 中": "현재 내용을 클립보드에 복사해 GitHub 이슈에 붙여넣을 수 있습니다",
        "将文件拖放到此处进行粉碎": "파쇄할 파일을 여기에 드롭하세요",
        "将模块渐变背景替换为中性的深色背景，以提升可读性。": "모듈의 그라데이션 배경을 중립적인 어두운 색으로 바꿔 가독성을 높입니다.",
