        "此扩展内置于 {browser}，无法移除。": "이 확장 프로그램은 {browser}에 내장되어 있어 제거할 수 없습니다.",
        "此扩展由管理策略安装，删除文件夹后 {browser} 会重新安装它。如果你不认识它，请在系统设置中搜索“描述文件”或“设备管理”，并移除你不认识的描述文件。": "이 확장 프로그램은 관리 정책으로 설치되었으므로 폴더를 삭제해도 {browser} 앱이 다시 설치합니다. 모르는 확장 프로그램이면 시스템 설정에서 프로필 또는 기기 관리를 검색하고 모르는 프로필을 모두 제거하세요.",
        "此操作不可撤销，不会进入废纸篓。": "이 작업은 영구적입니다. 휴지통으로 이동하지 않습니다.",
