        "没有订阅，没有广告，没有追踪。Mac Sai 是我和几位志愿者在业余时间做的。如果它帮你省下了买清理软件的钱，请我喝杯咖啡，让它对所有人继续免费。": "구독, 광고, 추적이 없습니다. 몇몇 자원봉사자와 함께 저녁과 주말에 Mac Sai를 개발합니다. 유료 정리 앱을 구입할 비용을 아꼈다면, 커피 한 잔의 후원으로 모두에게 무료로 제공하는 데 힘을 보태 주세요.",
