        "超过 30 天的 iPhone 和 iPad 本地备份。如果这是设备唯一的备份，请保留或先备份到 iCloud。": "30일이 지난 iPhone 및 iPad 로컬 백업입니다. 기기의 유일한 백업이라면 보관하거나 먼저 iCloud에 백업하세요.",
        "跟随系统": "시스템",
        "跨卷": "다른 볼륨",
        "跳过此版本": "이 버전 건너뛰기",
        "输入的二进制文件不是通用 Mach-O": "입력 바이너리가 유니버설 Mach-O가 아님",
        "运行 docker system prune，删除未使用的镜像、已停止的容器、未使用的网络和构建缓存。此操作不可撤销（不会进入废纸篓）。正在运行的容器、使用中的镜像和命名卷不受影响，磁盘映像 Docker.raw 也不会被直接删除。": "docker system prune을 실행하여 사용하지 않는 이미지, 중지된 컨테이너, 사용하지 않는 네트워크 및 빌드 캐시를 삭제합니다. 휴지통으로 이동하지 않으므로 되돌릴 수 없습니다. 실행 중인 컨테이너, 사용 중인 이미지 및 이름 있는 볼륨은 유지하며 Docker.raw 디스크 이미지를 직접 삭제하지 않습니다.",
        "运行中": "실행 중",
        "运行安全任务": "안전한 작업 실행",
        "运行时间": "가동 시간",
        "运行此任务": "이 작업 실행",
        "运行系统维护任务，让 Mac 保持健康": "시스템 유지 관리 작업을 실행하여 Mac을 건강하게 유지하세요",
        "运行维护脚本": "유지보수 스크립트 실행",
        "返回": "뒤로",
        "返回起点": "처음으로 돌아가기",
        "还原": "복원",
        "还原版本": "버전 복원",
        "还没有可恢复的清理记录": "되돌릴 정리 기록이 없습니다",
        "这只会忘掉恢复记录，废纸篓里的文件不会被动。之后就不能一键恢复这些清理了。": "복원 기록만 지웁니다. 휴지통의 파일은 그대로 있지만 이 정리 작업들을 더 이상 한 번의 클릭으로 복원할 수 없습니다.",
        "这台 Mac": "이 Mac",
        "这台 Mac 上没有找到 Docker 或 Xcode 模拟器。": "이 Mac에서 Docker 또는 Xcode 시뮬레이터를 찾을 수 없습니다.",
        "这次清理太大，只能恢复前 %ld 项。其余 %ld 项仍在废纸篓中，可在访达里手动放回。": "이 정리 항목은 너무 커서 전체를 추적할 수 없습니다. 처음 %ld개 항목만 복원할 수 있습니다. 나머지 %ld개는 아직 휴지통에 있으므로 Finder에서 다시 넣을 수 있습니다.",
        "这次清理，你没花一分钱。": "이번 정리에는 비용이 전혀 들지 않았습니다.",
        "进度": "진행상황",
        "退出": "종료",
        "退出监视器": "모니터 종료",
        "选中的项目会移到废纸篓，如有需要仍可恢复。": "선택한 항목은 휴지통으로 이동되며 필요한 경우 복구할 수 있습니다.",
        "选择一个应用以查看相关文件": "관련 파일을 보려면 앱을 선택하세요",
        "选择应用图标旁显示的紧凑数值。GPU 或电池温度不可用时显示 --。": "앱 아이콘 옆에 표시할 간단한 값을 선택하세요. GPU 또는 배터리 센서를 사용할 수 없으면 --로 표시됩니다.",
        "选择文件": "파일 선택",
        "选择要从清理中排除的文件夹。": "정리에서 제외할 폴더를 선택하세요.",
        "选择项目文件夹（例如 ~/Code），查找 node_modules、venv、target、build 等可重建目录。": "프로젝트 폴더(예: ~/Code)를 선택하여 node_modules, venv, target, build 등 다시 생성할 수 있는 폴더를 찾으세요.",
        "逐字节完全相同的副本。每个需要的文件请至少保留一份。": "바이트 단위로 동일한 복사본입니다. 필요한 각 파일의 복사본을 하나 이상 보관하세요.",
        "通常没有可见影响——这些脚本与 macOS 夜间自动运行的维护脚本相同。": "눈에 띄는 영향은 없습니다. macOS가 밤마다 자동으로 실행하는 것과 같은 스크립트입니다.",
        "通用": "일반",
        "通用二进制": "범용 바이너리",
        "通过精简低优先级本地快照回收可清除磁盘空间": "우선순위가 낮은 로컬 스냅샷을 줄여 제거 가능한 디스크 공간을 확보합니다.",
        "邮件保存在磁盘上的附件副本。IMAP 和 Exchange 账户可从服务器重新下载，POP 账户不行。": "Mail이 디스크에 저장한 첨부 파일의 사본입니다. IMAP 및 Exchange 계정은 서버에서 다시 다운로드할 수 있지만 POP 계정은 불가능합니다.",
        "邮件索引已移除。邮件将在下次启动时重建。": "Mail 색인이 제거되었습니다. Mail이 다음 실행 시 다시 생성합니다.",
        "邮件附件": "Mail 첨부 파일",
        "邮件附件的缓存副本。": "Mail 첨부 파일의 캐시된 사본입니다.",
        "部分可恢复": "일부 복원 가능",
        "释放内存": "RAM 확보",
        "释放可清除空间": "제거 가능한 공간 확보",
        "释放空间": "여유 공간 확보",
        "重复文件": "중복 파일",
        "重复文件检测会使用 SHA-256 哈希每个候选文件。\n大型个人目录可能需要 5–15 分钟。": "중복 검사 시 모든 후보 파일의 SHA-256 해시를 계산합니다.\n홈 폴더가 크면 5~15분 정도 걸릴 수 있습니다.",
        "重建 Spotlight 搜索索引，提高搜索准确性": "검색 정확도를 높이기 위해 Spotlight 검색 색인 재생성",
        "重建 Spotlight 索引": "Spotlight 색인 재생성",
        "重建“邮件”数据库索引，以修复搜索和性能问题": "검색 및 성능 문제를 해결하기 위해 Mail 데이터베이스 색인 재생성",
        "重建启动服务": "Launch Services 재구축",
        "重新扫描": "다시 검사",
        "重新扫描启动项": "시작 항목 다시 검사",
        "重新检查": "다시 확인",
        "重新读取已保存的网络": "저장된 네트워크 다시 로드",
        "重新读取扩展列表": "확장 프로그램 목록 새로고침",
        "重新读取权限列表": "권한 목록 새로고침",
        "重试": "재시도",
        "错误": "오류",
        "镜像": "이미지",
        "长时间未打开的文件。": "오랫동안 열지 않은 파일입니다.",
        "防护": "보호",
        "隐私清理": "개인 정보 보호",
        "需要在“系统设置 → 登录项”中批准": "시스템 설정 → 로그인 항목에서 승인 필요",
        "需要在“系统设置 → 通用 → 登录项”中批准": "시스템 설정 → 일반 → 로그인 항목에서 승인 필요",
        "需要完全磁盘访问权限": "전체 디스크 접근 권한 필요",
        "需要完全磁盘访问权限才能列出应用": "앱을 나열하려면 전체 디스크 접근 권한이 필요합니다",
        "非 APFS 卷": "APFS 볼륨이 아님",
        "非普通文件": "일반 파일이 아님",
        "音频": "오디오",
        "项目中已安装的依赖和构建产物。运行项目的安装或构建命令即可找回；之后第一次构建会更慢。": "프로젝트 내에 설치된 종속성과 빌드 결과물입니다. 프로젝트의 설치 또는 빌드 명령으로 다시 생성할 수 있으며, 이후 첫 빌드는 더 오래 걸립니다.",
        "项目垃圾": "프로젝트 불필요한 파일",
        "验证启动磁盘": "시동 디스크 확인",
        "高级": "고급",
        "麦克风": "마이크",
        "清理权限": "정리 권한",
        "允许 Mac Sai 扫描邮件、浏览器数据和其他受保护的文件夹。在系统设置中添加 Mac Sai 并开启权限，然后重新启动应用并重新扫描。": "Mac Sai가 Mail, 브라우저 데이터 및 기타 보호된 폴더를 검사할 수 있도록 허용합니다. 시스템 설정에서 Mac Sai를 추가하고 권한을 켠 다음 앱을 다시 시작하고 다시 검사하세요.",
        "打开完全磁盘访问设置": "전체 디스크 접근 권한 설정 열기",
        "管理员确认": "관리자 승인",
        "移动受保护的项目时，macOS 可能仍会要求密码或触控 ID。完全磁盘访问权限不能代替管理员确认。Mac Sai 不保存您的密码，也不能提前批准所有操作。": "보호된 항목을 이동할 때 macOS가 여전히 암호나 Touch ID를 요청할 수 있습니다. 전체 디스크 접근 권한은 관리자 승인을 대신하지 않습니다. Mac Sai는 암호를 저장하지 않으며 모든 작업을 미리 승인할 수도 없습니다.",
        "批量移到废纸篓": "그룹 단위로 휴지통으로 이동",
        "清理会将选中的项目分组交给 macOS，减少逐项请求。系统决定是否需要再次确认。取消后，当前组会先完成；已移动的项目仍会显示在清理历史中。": "정리 시 선택한 항목을 그룹으로 묶어 macOS에 전달하므로 개별 요청이 줄어듭니다. 추가 승인이 필요한지는 시스템이 결정합니다. 취소하면 현재 그룹이 먼저 완료되며, 이미 이동된 항목은 정리 기록에 계속 표시됩니다.",
        "权限": "권한",
        "另一项清理仍在进行中。": "다른 정리 작업이 아직 진행 중입니다.",
        "准备清理时文件已更改，请重新扫描。": "정리를 준비하는 동안 항목이 변경되었습니다. 다시 검사하세요.",
        "无法确认项目在废纸篓中的位置，请检查访达。": "휴지통에서 항목의 위치를 확인할 수 없습니다. Finder에서 확인하세요.",
        "macOS 未将此项目移到废纸篓。请检查权限并重新扫描。": "macOS가 이 항목을 휴지통으로 이동하지 않았습니다. 권한을 확인하고 다시 검사하세요.",
        "符号链接改变了清理路径。请在访达中检查。": "심볼릭 링크로 인해 정리 경로가 변경되었습니다. Finder에서 항목을 확인하세요.",
        "符号链接已跳过。": "심볼릭 링크를 건너뛰었습니다.",
        "取消后会先完成当前一组。": "취소하면 현재 그룹이 먼저 완료됩니다.",
        "清理已停止": "정리 중지됨",
        "已处理": "처리됨",
        "选中的文件夹与其内容计为一项。已经消失的文件会被跳过。": "선택한 폴더와 그 내용은 하나의 항목으로 계산됩니다. 이미 사라진 파일은 건너뜁니다.",
        "部分项目未能清理": "일부 항목을 정리하지 못함",
        "以上仅显示已完成的操作。移到废纸篓的项目可从清理历史恢复。请重新扫描以查看剩余或重新生成的文件。": "위에는 완료된 작업만 표시됩니다. 휴지통으로 이동한 항목은 정리 기록에서 복원할 수 있습니다. 남아 있거나 다시 생성된 파일을 확인하려면 다시 검사하세요.",
        "请逐项检查并选择可能的威胁和社区报告的文件。此复选框只能取消该类别中已选中的项目。": "가능한 위협과 커뮤니티에서 신고한 파일은 하나씩 확인하고 선택하세요. 이 체크박스로는 이 카테고리에서 선택된 항목의 선택 해제만 할 수 있습니다.",
        "全选": "모두 선택",
        "取消全选": "모두 선택 해제",
        "选择安全项目": "안전한 항목 선택",
        "选择所有允许自动勾选的项目。需要手动检查的类别和可能的威胁保持不选。": "자동 선택이 허용된 모든 항목을 선택합니다. 직접 확인해야 하는 카테고리와 가능한 위협은 선택되지 않은 상태로 유지됩니다.",
        "仅保留安全的临时文件、缓存、日志和残留文件。不选择个人数据、废纸篓或应用修改。": "안전한 임시 파일, 캐시, 로그 및 남은 파일만 선택된 상태로 유지합니다. 개인 데이터, 휴지통 및 앱 수정은 제외됩니다.",
        "选中的文件会移到废纸篓，如有需要仍可恢复。": "선택한 파일은 휴지통으로 이동되며 필요한 경우 복구할 수 있습니다.",
        "废纸篓中选中的项目将永久删除，无法恢复。": "휴지통에서 선택한 항목은 영구적으로 삭제되며 복구할 수 없습니다.",
        "应用中未使用的架构将被移除。恢复可能需要重新安装应用。": "앱에서 사용하지 않는 아키텍처가 제거됩니다. 복원하려면 앱을 다시 설치해야 할 수 있습니다.",
        "无法开启登录时启动：{message}": "로그인 시 실행을 켤 수 없음: {message}",
        "无法关闭登录时启动：{message}": "로그인 시 실행을 끌 수 없음: {message}",
        "提醒": "알림",
        "内存压力提醒": "메모리 압력 알림",
        "内存压力持续偏高时通知你。": "메모리 압력이 계속 높으면 알려 줍니다.",
        "交换空间提醒": "스왑 사용량 알림",
        "交换空间超过所选大小时通知一次，降到明显低于该值后才会再次提醒。": "스왑이 선택한 크기를 넘으면 한 번 알리고, 그보다 확실히 낮아진 후에만 다시 알립니다.",
        "不提醒": "꺼짐",
        "提醒由菜单栏小组件发送，需要保持开启。": "알림은 메뉴 막대 위젯이 보내므로 위젯이 켜져 있어야 합니다.",
        "交换空间 {size}": "스왑 {size}",
        "交换空间使用过高": "스왑 사용량이 높음",
        "你的 Mac 正在使用 {used} 交换空间，超过了你设置的 {limit} 提醒值。退出不用的应用可以减轻内存压力。": "Mac이 스왑을 {used} 사용하고 있어 설정한 알림 기준 {limit}을(를) 초과했습니다. 사용하지 않는 앱을 종료하면 메모리 압력이 줄어듭니다.",
        "Base 资源、Mac Sai 的界面语言以及你的 Mac 在“语言与地区”中设置的语言会始终保留。已勾选的语言会保留；未勾选的语言文件可由“系统垃圾”移除。": "Base 리소스, Mac Sai의 인터페이스 언어, Mac의 언어 및 지역에서 설정한 언어는 항상 유지됩니다. 선택한 언어는 유지되며, 선택하지 않은 언어 파일은 시스템 불필요한 파일에서 제거될 수 있습니다.",
        "可能的威胁": "가능한 위협",
        "Apple XProtect 特征：{name}": "Apple XProtect 서명: {name}",
        "在 Apple 的 Safari 扩展黑名单中：{name}": "Apple의 Safari 확장 프로그램 차단 목록에 있음: {name}",
        "名称与已知家族相符：{name}": "이름이 알려진 악성코드 계열과 일치: {name}",
        "启动代理会运行“{name}”": "Launch Agent가 “{name}”을(를) 실행함",
        "标记原因": "표시된 이유",
        "没有可直接移除的威胁": "Mac Sai가 제거할 수 있는 위협 없음",
        "已发现，但需要管理员才能移除": "발견되었지만 제거하려면 관리자 권한이 필요함",
        "这些项目位于 Mac Sai 无法修改的系统文件夹中。请在 Finder 中显示每一项，然后输入管理员密码将其移到废纸篓。": "이 항목은 Mac Sai가 수정할 수 없는 시스템 폴더에 있습니다. 각 항목을 Finder에서 보고 관리자 암호를 입력해 휴지통으로 이동하세요.",
        "Apple XProtect {version}：{count} 个哈希值，{blocked} 个被屏蔽的 Safari 扩展": "Apple XProtect {version}: 해시 {count}개, 차단된 Safari 확장 프로그램 {blocked}개",
