        "在黑名单上或由社区报告、但也可能是你有意安装的软件的项目。": "차단 목록과 일치하거나 커뮤니티에서 신고했지만 의도적으로 설치한 소프트웨어일 수도 있는 항목입니다.",
        "不会预先勾选。黑名单可能也涵盖曾经正当的软件的旧版本，社区报告也未经厂商确认，删除前请逐个核对。": "미리 선택되지 않습니다. 차단 목록에는 한때 정상이었던 소프트웨어의 이전 버전이 포함될 수 있고 커뮤니티 신고는 제조사가 확인한 것이 아니므로, 제거하기 전에 각 항목을 확인하세요.",
        "正在比对 XProtect 和 MalwareBazaar 哈希值...": "XProtect 및 MalwareBazaar 해시 대조 중...",
        "已报告至 MalwareBazaar：{name}": "MalwareBazaar에 신고됨: {name}",
        "MalwareBazaar：未启用（可在设置中添加免费的 Auth-Key）": "MalwareBazaar: 꺼짐(설정에서 무료 Auth-Key를 추가하세요)",
