        "版本 {version}：{hashes} 个哈希值，{blocked} 个被屏蔽的 Safari 扩展。由 macOS 自动更新。": "버전 {version}: 해시 {hashes}개, 차단된 Safari 확장 프로그램 {blocked}개. macOS가 자동으로 최신 상태로 유지합니다.",
        "可选。按下“立即更新”时，使用你免费的 abuse.ch Auth-Key 下载最近报告的 macOS 恶意软件样本哈希值。每次请求只发送你的 Auth-Key 和查询内容，绝不发送文件哈希值或路径。如果某个哈希与已签名的文件匹配，macOS 会向 Apple 查询其签名证书是否已被吊销。匹配项不会预先勾选。": "선택 사항입니다. 지금 업데이트를 누르면 무료 abuse.ch Auth-Key를 사용해 최근 신고된 macOS 악성코드 샘플의 해시를 다운로드합니다. 각 요청에는 Auth-Key와 조회 내용만 전송되며 파일 해시나 경로는 절대 전송되지 않습니다. 해시가 서명된 파일과 일치하면 macOS가 Apple에 해당 서명 인증서가 폐기되었는지 확인합니다. 일치 항목은 미리 선택되지 않습니다.",
