        "macOS 的“哪类文件由哪个应用打开”数据库会被清除并重建。完成前（通常数小时），双击文件可能失败或打开错误应用，默认应用设置可能重置，Spotlight 启动应用也可能不可用。重启可加快恢复。": "macOS 的“哪類檔案由哪個應用開啟”資料庫會被清除並重建。完成前（通常數小時），雙擊檔案可能失敗或開啟錯誤應用，預設應用設定可能重置，Spotlight 啟動應用也可能不可用。重啟可加快恢復。",
