        "无法将密钥保存到钥匙串。": "無法將金鑰儲存到鑰匙圈。",
        "无法移除密钥或哈希值。": "無法移除金鑰或雜湊值。",
        "Auth-Key 被拒绝。请在 auth.abuse.ch 检查。": "Auth-Key 被拒絕。請在 auth.abuse.ch 檢查。",
        "尚未下载哈希值。": "尚未下載雜湊值。",
        "已更新：新增 {added} 个，共 {total} 个哈希值。": "已更新：新增 {added} 個，共 {total} 個雜湊值。",
