        "Mac Sai 仍在完成当前操作。您可以等待操作完成后退出并安装更新，或留在应用中。": "Mac Sai termine encore une opération. Vous pouvez attendre, puis quitter l’application et installer la mise à jour, ou rester dans l’application.",
