        "恢复这次清理？": "Restaurer ce nettoyage ?",
        "每一项都会放回原位置。原位置已有的文件绝不会被覆盖。": "Chaque élément retrouve son emplacement d'origine. Un fichier déjà présent à cet emplacement n'est jamais écrasé.",
        "这次清理太大，只能恢复前 %ld 项。其余 %ld 项仍在废纸篓中，可在访达里手动放回。": "Ce nettoyage était trop volumineux pour être suivi en entier : seuls les %ld premiers éléments peuvent être restaurés. Les %ld autres sont toujours dans la corbeille, vous pouvez les remettre en place depuis le Finder.",
