        "不会预先勾选。黑名单可能也涵盖曾经正当的软件的旧版本，社区报告也未经厂商确认，删除前请逐个核对。": "Rien n'est présélectionné. Une liste de blocage peut aussi couvrir d'anciennes versions de logiciels autrefois légitimes, et aucun éditeur ne confirme les signalements de la communauté, donc vérifiez chaque élément avant de le supprimer.",
