        "版本 {version}：{hashes} 个哈希值，{blocked} 个被屏蔽的 Safari 扩展。由 macOS 自动更新。": "Version {version} : {hashes} hachages, {blocked} extensions Safari bloquées. macOS la tient à jour.",
        "可选。按下“立即更新”时，使用你免费的 abuse.ch Auth-Key 下载最近报告的 macOS 恶意软件样本哈希值。每次请求只发送你的 Auth-Key 和查询内容，绝不发送文件哈希值或路径。如果某个哈希与已签名的文件匹配，macOS 会向 Apple 查询其签名证书是否已被吊销。匹配项不会预先勾选。": "Facultatif. Quand vous cliquez sur Mettre à jour maintenant, télécharge les hachages des échantillons de logiciels malveillants macOS récemment signalés avec votre Auth-Key abuse.ch gratuite. Chaque requête n'envoie que votre Auth-Key et la requête, jamais de hachages ni de chemins de fichiers. Si un hachage correspond à un fichier signé, macOS demande à Apple si son certificat de signature a été révoqué. Les correspondances ne sont jamais présélectionnées.",
