        "支持文件": "Supportdateien",
        "Spotlight 没有应用的使用记录": "Spotlight hat keinen Nutzungsverlauf für deine Apps",
        "无法判断哪些应用未被使用。请检查 Spotlight 索引是否已开启。": "Mac Sai kann nicht erkennen, welche Apps ungenutzt sind. Prüfe, ob die Spotlight-Indexierung aktiviert ist.",
        "以后再说": "Vielleicht später",
        "不再提示": "Nicht mehr fragen",
        "谢谢你。正因为有你，它才能一直免费。": "Danke. Wegen Leuten wie dir bleibt das kostenlos.",
        "支持 Mac Sai": "Mac Sai unterstützen",
        "支持者": "Unterstützer",
        "感谢你们让 Mac Sai 保持免费：{names}。": "Danke, dass ihr Mac Sai kostenlos haltet: {names}.",
        "支持 Mac Sai 的会员会列在这里。来做第一个吧。": "Hier stehen die Mitglieder, die Mac Sai kostenlos halten. Werde das erste.",
