        "仅移除 macOS 已标记可清理的 Time Machine 本地快照；不会删除你主动需要的内容。": "Lokale Time-Machine-Schnappschüsse, die macOS bereits zur Bereinigung markiert hat, werden entfernt. Aktiv benötigte Daten werden nicht gelöscht.",
