        "在设置中打开": "In Einstellungen öffnen",
        "Safari 扩展随 App 一起安装，由 macOS 管理，因此此列表只读。将改为打开“设置”。": "Safari-Erweiterungen kommen mit Apps und werden von macOS verwaltet, daher ist diese Liste schreibgeschützt. Stattdessen werden die Einstellungen geöffnet.",
        "如果 {browser} 已关闭，扩展文件夹会移到废纸篓。如果它正在运行，则不会删除任何内容，并会告诉你在哪里移除。如果你开启了 {browser} 同步，它可能会重新安装此扩展。": "Wenn {browser} geschlossen ist, wird der Erweiterungsordner in den Papierkorb gelegt. Ist {browser} geöffnet, wird nichts gelöscht und du erfährst, wo du die Erweiterung entfernen kannst. Wenn du die Synchronisierung von {browser} nutzt, kann die Erweiterung erneut installiert werden.",
        "已将扩展移到废纸篓。": "Die Erweiterung wurde in den Papierkorb gelegt.",
        "Mac Sai 无法确认此扩展的文件夹可以安全移除，因此未删除任何内容。": "Mac Sai konnte nicht bestätigen, dass der Ordner dieser Erweiterung sicher entfernt werden kann, daher wurde nichts gelöscht.",
        "无法移到废纸篓：": "Konnte nicht in den Papierkorb gelegt werden: ",
        "Chrome 正在运行，因此未删除任何内容。请在 Chrome 中通过“窗口 > 扩展程序”移除此扩展。": "Chrome ist geöffnet, daher wurde nichts gelöscht. Entferne die Erweiterung in Chrome über Fenster > Erweiterungen.",
        "Firefox 正在运行，因此未删除任何内容。请在 Firefox 中通过“工具 > 附加组件和主题”移除此扩展。": "Firefox ist geöffnet, daher wurde nichts gelöscht. Entferne die Erweiterung in Firefox über Extras > Add-ons und Themes.",
        "{browser} 正在运行，因此未删除任何内容。请在 {browser} 的地址栏中打开 {url} 来移除此扩展。": "{browser} ist geöffnet, daher wurde nichts gelöscht. Entferne die Erweiterung in {browser}, indem du {url} in der Adressleiste öffnest.",
        "此扩展由管理策略安装，删除文件夹后 {browser} 会重新安装它。如果你不认识它，请在系统设置中搜索“描述文件”或“设备管理”，并移除你不认识的描述文件。": "Diese Erweiterung wurde per Verwaltungsrichtlinie installiert, daher würde {browser} sie erneut installieren. Wenn du sie nicht kennst, suche in den Systemeinstellungen nach „Profile“ oder „Geräteverwaltung“ und entferne jedes Profil, das du nicht kennst.",
        "此扩展内置于 {browser}，无法移除。": "Diese Erweiterung ist in {browser} integriert und kann nicht entfernt werden.",
        "开发者磁盘占用": "Festplattenfresser",
        "Docker 和 Xcode 模拟器占用的空间。只显示在这台 Mac 上找到的工具，且不会自动勾选任何项目。": "Speicherplatz, den Docker und Xcode-Simulatoren belegen. Es werden nur die Tools angezeigt, die auf diesem Mac gefunden wurden, und nichts wird für dich vorausgewählt.",
        "Xcode 模拟器": "Xcode-Simulatoren",
        "不可用的模拟器": "Nicht verfügbarer Simulator",
        "旧版运行时": "Ältere Laufzeitumgebung",
        "清理所选 Docker 项目…": "Ausgewählte Docker-Objekte bereinigen …",
        "删除所选模拟器项目…": "Ausgewählte Simulator-Objekte löschen …",
        "已找到 Docker，但它没有响应。请先启动 Docker Desktop，然后点“刷新”。": "Docker ist installiert, reagiert aber nicht. Starte Docker Desktop und klicke dann auf „Aktualisieren“.",
        "这台 Mac 上没有找到 Docker 或 Xcode 模拟器。": "Auf diesem Mac wurden weder Docker noch Xcode-Simulatoren gefunden.",
        "永久清理所选 Docker 项目？": "Ausgewählte Docker-Objekte endgültig bereinigen?",
        "永久清理": "Endgültig bereinigen",
        "永久删除所选模拟器项目？": "Ausgewählte Simulator-Objekte endgültig löschen?",
        "删除运行时会先关闭正在使用它的模拟器，这些模拟器之后将不可用。": "Beim Löschen einer Laufzeitumgebung werden Simulatoren, die sie nutzen, zuerst beendet und sind danach nicht mehr verfügbar.",
        "此操作不可撤销，不会进入废纸篓。": "Das ist endgültig. Nichts landet im Papierkorb.",
        "清理完成": "Bereinigt",
        "删除完成": "Gelöscht",
        "未能完成": "Fehlgeschlagen",
        "超时，已停止": "Zeitüberschreitung, gestoppt",
        "已停止": "Gestoppt",
        "未找到 Docker": "Docker nicht gefunden",
        "镜像": "Images",
        "容器": "Container",
        "卷": "Volumes",
        "构建缓存": "Build-Cache",
        "清理只会删除悬空（无标签）镜像，带标签的镜像会保留。": "Beim Bereinigen werden nur verwaiste Images ohne Tag entfernt. Images mit Tag bleiben erhalten.",
        "清理会永久删除所有已停止的容器及其中的数据。正在运行的容器不受影响。": "Beim Bereinigen werden alle gestoppten Container samt ihren Daten endgültig gelöscht. Laufende Container bleiben unberührt.",
        "卷可能保存着数据库等数据，Mac Sai 不会清理它们。如需删除，请使用 Docker Desktop 或 Docker 命令行。": "Volumes können Datenbankdaten enthalten, deshalb lässt Mac Sai sie in Ruhe. Um sie zu entfernen, nutze Docker Desktop oder die Docker-CLI.",
        "清理会删除悬空的构建缓存。下次构建可能会变慢。": "Beim Bereinigen wird verwaister Build-Cache entfernt. Dein nächster Build kann langsamer sein.",
        "项目垃圾": "Projektmüll",
        "代码项目中的依赖和构建文件夹。": "Abhängigkeits- und Build-Ordner in deinen Code-Projekten.",
        "项目中已安装的依赖和构建产物。运行项目的安装或构建命令即可找回；之后第一次构建会更慢。": "Installierte Abhängigkeiten und Build-Ergebnisse in deinen Projekten. Der Installations- oder Build-Befehl des Projekts holt sie zurück; der erste Build danach dauert länger.",
        "选择项目文件夹（例如 ~/Code），查找 node_modules、venv、target、build 等可重建目录。": "Wähle einen Projektordner (z. B. ~/Code), um wiederherstellbare Ordner wie node_modules, venvs, target und build zu finden.",
        "不会自动勾选。": "Nichts wird automatisch ausgewählt.",
        "未找到项目垃圾": "Kein Projektmüll gefunden",
        "请选择你的项目文件夹，而不是系统文件夹或资源库。": "Wähle deinen Projektordner, keinen Systemordner und nicht die Library.",
        "正在查找项目…": "Projekte werden gesucht …",
        "正在计算文件夹大小…": "Ordnergrößen werden berechnet …",
        "清理历史": "Bereinigungsverlauf",
        "把最近一次清理整批恢复到原位置。已清空废纸篓或原路径已有文件的项会被跳过。": "Stell eine ganze Bereinigung mit einem Klick wieder her. Objekte, die schon aus dem Papierkorb gelöscht wurden oder an deren Ort inzwischen eine neue Datei liegt, werden übersprungen.",
        "清除历史": "Verlauf löschen",
        "还没有可恢复的清理记录": "Noch keine Bereinigungen zum Wiederherstellen",
        "%ld 项": "Objekte: %ld",
        "部分可恢复": "Teilweise wiederherstellbar",
        "恢复": "Wiederherstellen",
        "恢复这次清理？": "Diese Bereinigung wiederherstellen?",
        "每一项都会放回原位置。原位置已有的文件绝不会被覆盖。": "Jedes Objekt kommt an seinen ursprünglichen Ort zurück. Eine Datei, die dort schon liegt, wird nie überschrieben.",
        "这次清理太大，只能恢复前 %ld 项。其余 %ld 项仍在废纸篓中，可在访达里手动放回。": "Diese Bereinigung war zu groß, um sie vollständig zu speichern: Nur die ersten %ld Objekte lassen sich wiederherstellen. Die übrigen %ld liegen weiter im Papierkorb, du kannst sie im Finder zurücklegen.",
        "恢复完成": "Wiederherstellung abgeschlossen",
        "已恢复：%ld": "Wiederhergestellt: %ld",
        "已从废纸篓清空：%ld": "Schon aus dem Papierkorb gelöscht: %ld",
        "原位置已有文件，已跳过：%ld": "Übersprungen, Ort belegt: %ld",
        "无法恢复：%ld": "Nicht wiederherstellbar: %ld",
