        "这只会忘掉恢复记录，废纸篓里的文件不会被动。之后就不能一键恢复这些清理了。": "Dadurch wird nur die Wiederherstellungsliste vergessen. Im Papierkorb wird nichts angerührt, aber du kannst diese Bereinigungen danach nicht mehr mit einem Klick wiederherstellen.",
