        "自动化": "Automatisierung",
        "自动检查更新": "Automatisch nach Updates suchen",
        "Base 资源、Mac Sai 的界面语言以及你的 Mac 在“语言与地区”中设置的语言会始终保留。已勾选的语言会保留；未勾选的语言文件可由“系统垃圾”移除。": "Basisressourcen, die Oberflächensprachen von Mac Sai und die Sprachen aus den Einstellungen „Sprache & Region“ deines Mac bleiben immer erhalten. Markierte Sprachen werden behalten; nicht markierte Sprachdateien können durch Systemmüll entfernt werden.",
