        "错误": "Fehler",
        "长时间未打开的文件。": "Dateien, die du lange nicht geöffnet hast.",
        "防护": "Schutz",
        "隐私清理": "Datenschutz",
        "需要在“系统设置 → 登录项”中批准": "Freigabe unter Systemeinstellungen → Anmeldeobjekte erforderlich",
        "需要在“系统设置 → 通用 → 登录项”中批准": "Freigabe unter Systemeinstellungen → Allgemein → Anmeldeobjekte erforderlich",
        "需要完全磁盘访问权限": "Festplattenvollzugriff erforderlich",
        "需要完全磁盘访问权限才能列出应用": "Festplattenvollzugriff zum Auflisten der Apps erforderlich",
        "非 APFS 卷": "kein APFS-Volume",
        "非普通文件": "keine reguläre Datei",
        "音频": "Audio",
        "验证启动磁盘": "Startvolume prüfen",
        "高级": "ERWEITERT",
        "麦克风": "Mikrofon",
        // Review screen: why each category is safe to clean.
        "会自动重建": "Wird automatisch neu erstellt",
        "可安全移除": "Sicher entfernbar",
        "清理前请检查": "Vor dem Bereinigen prüfen",
        "应用临时文件。每个应用下次启动时会自动重新生成。": "Temporäre App-Dateien. Werden beim nächsten Start der jeweiligen App automatisch neu erstellt.",
        "由 macOS 自行管理的缓存，需要时会自动重建。": "Von macOS selbst verwaltete Caches. Das System erstellt sie bei Bedarf automatisch neu.",
        "下载和构建缓存。npm、Cargo、pip、Homebrew 和 Gradle 会在下次安装或构建时重新下载所需内容。": "Download- und Build-Caches. npm, Cargo, pip, Homebrew und Gradle laden Benötigtes bei der nächsten Installation oder dem nächsten Build erneut herunter.",
        "仅编辑器缓存。Cursor 和 Antigravity 下次启动时会重新生成；你的设置和扩展不受影响。": "Nur Editor-Caches. Cursor und Antigravity erstellen sie beim nächsten Start neu; Einstellungen und Erweiterungen bleiben unberührt.",
        "仅临时和缓存文件夹。Claude 和 Codex 会按需重新生成；绝不包含历史、记忆和会话。": "Nur Arbeits- und Cache-Ordner. Claude und Codex erstellen sie bei Bedarf neu; Verlauf, Gedächtnis und Sitzungen sind nie enthalten.",
        "应用为排查问题写下的诊断记录。应用不会回读旧日志，运行时会写新的日志。": "Diagnosetexte, die Apps zur Fehlersuche geschrieben haben. Apps lesen alte Protokolle nicht wieder ein und beginnen beim Ausführen neue.",
        "macOS 诊断日志。仅在排查过去的问题时有用；macOS 会继续写入新日志。": "Diagnoseprotokolle von macOS. Nur bei der Untersuchung früherer Probleme nützlich; macOS schreibt laufend neue.",
        "无法读取的设置文件，或其应用已不再安装。这台 Mac 上没有任何东西在使用它们。": "Einstellungsdateien, die nicht lesbar sind oder deren App nicht mehr installiert ist. Nichts auf diesem Mac verwendet sie.",
        "指向已不存在应用的登录项，因此无法启动任何东西。": "Anmeldeeinträge, die auf nicht mehr vorhandene Apps verweisen und daher nichts starten können.",
        "失败或被放弃的下载留下的文件。如仍需要，请重新下载。": "Reste fehlgeschlagener oder abgebrochener Downloads. Lade die Datei erneut herunter, falls du sie noch brauchst.",
        "未完成下载的部分文件和超过一天的临时文件。下载仍在进行时请勿清理。": "Teildateien unvollständiger Downloads und mehr als einen Tag alte temporäre Dateien. Nicht bereinigen, solange ein Download noch läuft.",
        "应用在一周多以前下载的安装包。安装程序运行后就不再需要，需要时可重新下载。": "Installationspakete, die Apps vor über einer Woche heruntergeladen haben. Nach der Installation werden sie nicht mehr benötigt und lassen sich erneut herunterladen.",
        "以已不再安装的应用命名的支持文件夹（每行的名称就是该应用的 ID）。以后重新安装该应用会从头开始。": "Support-Ordner, benannt nach einer nicht mehr installierten App (der Name in jeder Zeile ist die ID dieser App). Wird die App später neu installiert, startet sie ohne alte Daten.",
        "你不使用的语言翻译。移除会修改应用包；如需恢复请重新安装应用。": "Übersetzungen für Sprachen, die du nicht nutzt. Das Entfernen ändert das App-Paket; installiere die App neu, um sie zurückzubekommen.",
        "文档的旧自动保存版本。当前版本会保留，但清理后无法再浏览旧版本。": "Ältere automatisch gesicherte Versionen deiner Dokumente. Die aktuelle Version bleibt, ältere lassen sich danach nicht mehr durchsuchen.",
        "超过 30 天的 iPhone 和 iPad 本地备份。如果这是设备唯一的备份，请保留或先备份到 iCloud。": "Lokale iPhone- und iPad-Backups, die älter als 30 Tage sind. Ist es das einzige Backup eines Geräts, behalte es oder sichere zuerst in iCloud.",
        "从应用中移除这台 Mac 无法运行的 CPU 代码。会直接修改应用；只有重新安装才能撤销。": "Entfernt CPU-Code aus Apps, den dieser Mac nicht ausführen kann. Ändert die Apps direkt; nur eine Neuinstallation macht es rückgängig.",
        "DerivedData 和 Previews 会在下次构建时重建，Device Support 会在连接设备时重新复制。Archives 和模拟器数据无法重新生成；如需旧构建或崩溃符号请保留。": "DerivedData und Previews werden beim nächsten Build neu erstellt, Device Support wird beim Verbinden eines Geräts neu kopiert. Archives und Simulatordaten lassen sich nicht wiederherstellen; behalte sie, wenn du alte Builds oder Absturzsymbole brauchst.",
        "已不在这台 Mac 上的账户的整个个人文件夹。请逐个核对名称：暂时离线的网络账户看起来完全一样。": "Komplette Benutzerordner von Accounts, die nicht mehr auf diesem Mac sind. Prüfe jeden Namen: Ein kurz nicht erreichbarer Netzwerk-Account sieht genauso aus.",
        "下载文件夹中超过一周的磁盘映像，通常是已运行过的安装程序。如需要可重新下载。": "Disk-Images in Downloads, die älter als eine Woche sind, meist bereits ausgeführte Installer. Lade sie bei Bedarf erneut herunter.",
        "邮件保存在磁盘上的附件副本。IMAP 和 Exchange 账户可从服务器重新下载，POP 账户不行。": "Kopien von Anhängen, die Mail auf der Festplatte gespeichert hat. Bei IMAP- und Exchange-Accounts lädt Mail sie erneut vom Server, bei POP nicht.",
        "已在废纸篓中。清倒是永久性的，无法撤销。": "Bereits im Papierkorb. Das Entleeren ist endgültig und kann nicht rückgängig gemacht werden.",
        "匹配已知恶意软件特征。如果它属于你有意安装的软件，请先检查路径。": "Entspricht einer bekannten Malware-Signatur. Prüfe zuerst den Pfad, falls es zu absichtlich installierter Software gehört.",
        "你的浏览历史和跟踪数据。清理后无法恢复；Cookie 和登录会话会保留。": "Dein Browserverlauf und Tracking-Daten. Nach dem Bereinigen nicht wiederherstellbar; Cookies und Anmeldungen bleiben.",
        "最近项目列表和类似痕迹。应用的“最近打开”菜单将会清空。": "Listen zuletzt verwendeter Objekte und ähnliche Spuren. Die Menüs „Zuletzt geöffnet“ der Apps sind danach leer.",
        "你自己的文件，仅按大小挑选。这里没有任何东西天生就是垃圾；请逐个检查。": "Deine eigenen Dateien, nur nach Größe ausgewählt. Nichts davon ist automatisch Müll; prüfe jede einzelne.",
        "很久没打开过的你自己的文件。旧并不代表不需要；请逐个检查。": "Deine eigenen Dateien, die du lange nicht geöffnet hast. Alt heißt nicht überflüssig; prüfe jede einzelne.",
        "逐字节完全相同的副本。每个需要的文件请至少保留一份。": "Byte für Byte identische Kopien. Behalte von jeder benötigten Datei mindestens eine Kopie.",
        "可能的威胁": "Mögliche Bedrohungen",
        "Apple XProtect 特征：{name}": "Apple-XProtect-Signatur: {name}",
        "在 Apple 的 Safari 扩展黑名单中：{name}": "Auf Apples Sperrliste für Safari-Erweiterungen: {name}",
        "名称与已知家族相符：{name}": "Name entspricht einer bekannten Familie: {name}",
        "启动代理会运行“{name}”": "Startobjekt führt „{name}“ aus",
        "标记原因": "Warum diese markiert wurden",
        "没有可直接移除的威胁": "Keine Bedrohungen, die Mac Sai entfernen kann",
        "已发现，但需要管理员才能移除": "Gefunden, aber zum Entfernen sind Administratorrechte nötig",
        "这些项目位于 Mac Sai 无法修改的系统文件夹中。请在 Finder 中显示每一项，然后输入管理员密码将其移到废纸篓。": "Sie liegen in Systemordnern, die Mac Sai nicht ändern kann. Zeige jedes Objekt im Finder an und lege es dort mit deinem Administratorpasswort in den Papierkorb.",
        "Apple XProtect {version}：{count} 个哈希值，{blocked} 个被屏蔽的 Safari 扩展": "Apple XProtect {version}: {count} Hashes, {blocked} gesperrte Safari-Erweiterungen",
        "未在这台 Mac 上找到 Apple XProtect 数据": "Keine Apple-XProtect-Daten auf diesem Mac gefunden",
        "在黑名单上或由社区报告、但也可能是你有意安装的软件的项目。": "Treffer auf einer Sperrliste oder aus Community-Meldungen, die auch absichtlich installierte Software sein können.",
        "不会预先勾选。黑名单可能也涵盖曾经正当的软件的旧版本，社区报告也未经厂商确认，删除前请逐个核对。": "Nichts ist vorausgewählt. Eine Sperrliste kann auch ältere Versionen einst seriöser Software abdecken, und Community-Meldungen bestätigt kein Hersteller. Prüfe daher jedes Objekt, bevor du es entfernst.",
        "正在比对 XProtect 和 MalwareBazaar 哈希值...": "XProtect- und MalwareBazaar-Hashes werden abgeglichen...",
        "已报告至 MalwareBazaar：{name}": "An MalwareBazaar gemeldet: {name}",
        "MalwareBazaar：未启用（可在设置中添加免费的 Auth-Key）": "MalwareBazaar: aus (füge in den Einstellungen einen kostenlosen Auth-Key hinzu)",
        "MalwareBazaar：{count} 个哈希值，更新于 {date}": "MalwareBazaar: {count} Hashes, aktualisiert am {date}",
        "恶意软件数据库": "Malware-Datenbanken",
        "版本 {version}：{hashes} 个哈希值，{blocked} 个被屏蔽的 Safari 扩展。由 macOS 自动更新。": "Version {version}: {hashes} Hashes, {blocked} gesperrte Safari-Erweiterungen. macOS hält sie aktuell.",
        "可选。按下“立即更新”时，使用你免费的 abuse.ch Auth-Key 下载最近报告的 macOS 恶意软件样本哈希值。每次请求只发送你的 Auth-Key 和查询内容，绝不发送文件哈希值或路径。如果某个哈希与已签名的文件匹配，macOS 会向 Apple 查询其签名证书是否已被吊销。匹配项不会预先勾选。": "Optional. Lädt beim Klick auf „Jetzt aktualisieren“ mit deinem kostenlosen abuse.ch-Auth-Key die Hashes kürzlich gemeldeter macOS-Malware-Proben. Jede Anfrage sendet nur deinen Auth-Key und die Abfrage, niemals Datei-Hashes oder Pfade. Passt ein Hash zu einer signierten Datei, fragt macOS bei Apple nach, ob ihr Signaturzertifikat widerrufen wurde. Treffer werden nie vorausgewählt.",
        "abuse.ch Auth-Key": "abuse.ch-Auth-Key",
        "保存密钥": "Schlüssel sichern",
        "移除密钥和哈希值": "Schlüssel und Hashes entfernen",
        "立即更新": "Jetzt aktualisieren",
        "获取免费密钥": "Kostenlosen Schlüssel holen",
        "正在更新…": "Wird aktualisiert …",
