        "Auth-Key 被拒绝。请在 auth.abuse.ch 检查。": "Der Auth-Key wurde abgelehnt. Prüfe ihn auf auth.abuse.ch.",
        "尚未下载哈希值。": "Noch keine Hashes geladen.",
