        "仅保留安全的临时文件、缓存、日志和残留文件。不选择个人数据、废纸篓或应用修改。": "Mantiene selezionati solo file temporanei sicuri, cache, registri e residui. Esclude dati personali, Cestino e modifiche alle app.",
