        "按上次打开时间列出应用，并按占用空间排序。一键转到卸载器。": "Elenca le app non aperte di recente, ordinate per spazio occupato. Con un clic le invii al Disinstallatore.",
        "正在读取扩展…": "Lettura estensioni in corso…",
        "原位置已有文件，已跳过：%ld": "Posizione originale occupata, saltati: %ld",
        "扫描 Mac 中的垃圾文件、恶意威胁\n和性能问题": "Scansiona il Mac alla ricerca di file non necessari, minacce malware\ne problemi di prestazioni",
        "此扩展内置于 {browser}，无法移除。": "Questa estensione è integrata in {browser} e non può essere rimossa.",
        "未使用的应用": "App inutilizzate",
        "名称与已知广告软件家族相符。这只是提示，并非确认。": "Il nome corrisponde a una nota famiglia di adware. Si tratta di un avviso, non di un rilevamento confermato.",
        "未找到 Docker": "Docker non trovato",
        "卷可能保存着数据库等数据，Mac Sai 不会清理它们。如需删除，请使用 Docker Desktop 或 Docker 命令行。": "I volumi possono contenere database o dati permanenti, quindi Mac Sai non li elimina. Per rimuoverli, usa Docker Desktop o il comando docker.",
        "不可用的模拟器": "Simulatore non disponibile",
        "后台": "In background",

        "这次清理，你没花一分钱。": "Questa pulizia non ti è costata nulla.",
        "没有订阅，没有广告，没有追踪。Mac Sai 是我和几位志愿者在业余时间做的。如果它帮你省下了买清理软件的钱，请我喝杯咖啡，让它对所有人继续免费。": "Nessun abbonamento, nessuna pubblicità, nessun tracciamento. Sviluppo Mac Sai la sera e nei fine settimana con alcuni volontari. Se ti ha evitato di pagare per un software di pulizia, offrimi un caffè per mantenerlo gratuito per tutti.",
        "请我喝杯咖啡": "Offrimi un caffè",
        "以后再说": "Più tardi",
        "不再提示": "Non chiedere più",
        "谢谢你。正因为有你，它才能一直免费。": "Grazie. È grazie a persone come te che rimane gratuito.",
        "支持 Mac Sai": "Supporta Mac Sai",
        "支持者": "Sostenitori",
        "感谢你们让 Mac Sai 保持免费：{names}。": "Grazie per mantenere Mac Sai gratuito: {names}.",
        "支持 Mac Sai 的会员会列在这里。来做第一个吧。": "Qui compaiono i membri che mantengono Mac Sai gratuito. Diventa il primo.",
