        "仅移除 macOS 已标记可清理的 Time Machine 本地快照；不会删除你主动需要的内容。": "Vengono rimosse solo le istantanee locali di Time Machine che macOS ha già contrassegnato per l'eliminazione; nulla di ciò di cui hai bisogno verrà eliminato.",
