        "以开源方式让你的 Mac 保持干净、快速和安全。": "Il modo open source per mantenere il tuo Mac pulito, veloce e sicuro.",
        "优化": "Ottimizzazione",
        "优化你的 Mac": "Ottimizza il tuo Mac",
        "会产生几分钟磁盘活动。该操作为只读，无论结果如何都不会更改磁盘内容。": "Richiede qualche minuto di attività del disco. L'operazione è di sola lettura: il contenuto del disco non viene modificato in nessun caso.",
        "会删除本地 Time Machine 快照以释放空间。远程或备份盘上的快照不受影响，你仍可从 Time Machine 备份恢复。": "Le istantanee locali di Time Machine vengono eliminate per liberare spazio. Le istantanee su dischi remoti o di backup restano intatte; potrai comunque effettuare il ripristino dal backup di Time Machine.",
