        "运行 docker system prune，删除未使用的镜像、已停止的容器、未使用的网络和构建缓存。此操作不可撤销（不会进入废纸篓）。正在运行的容器、使用中的镜像和命名卷不受影响，磁盘映像 Docker.raw 也不会被直接删除。": "Esegue docker system prune, rimuovendo le immagini non utilizzate, i container arrestati, le reti non usate e la cache di compilazione. Operazione irreversibile (i file non passano dal Cestino). Container in esecuzione, immagini in uso e volumi con nome restano intatti; l'immagine disco Docker.raw non viene mai eliminata direttamente.",
