        "清理前请检查": "Verifica prima di pulire",
        "应用临时文件。每个应用下次启动时会自动重新生成。": "File temporanei delle app. Ricreati automaticamente al prossimo avvio di ciascuna app.",
        "由 macOS 自行管理的缓存，需要时会自动重建。": "Cache gestite direttamente da macOS. Ricostruite automaticamente al bisogno.",
        "下载和构建缓存。npm、Cargo、pip、Homebrew 和 Gradle 会在下次安装或构建时重新下载所需内容。": "Cache di download e compilazione. npm, Cargo, pip, Homebrew e Gradle riscaricheranno quanto necessario alla prossima installazione o compilazione.",
        "仅编辑器缓存。Cursor 和 Antigravity 下次启动时会重新生成；你的设置和扩展不受影响。": "Solo cache degli editor. Cursor e Antigravity le ricreeranno al prossimo avvio; impostazioni ed estensioni restano intatte.",
        "仅临时和缓存文件夹。Claude 和 Codex 会按需重新生成；绝不包含历史、记忆和会话。": "Solo cartelle temporanee e di cache. Claude e Codex le ricreano al bisogno; cronologia, memoria e sessioni non sono mai incluse.",
        "应用为排查问题写下的诊断记录。应用不会回读旧日志，运行时会写新的日志。": "Testo di diagnostica scritto dalle app per la risoluzione dei problemi. Le app non rileggono i vecchi registri e ne avviano di nuovi durante l'esecuzione.",
        "macOS 诊断日志。仅在排查过去的问题时有用；macOS 会继续写入新日志。": "Registri diagnostici di macOS. Utili solo per analizzare problemi passati; macOS continuerà a scriverne di nuovi.",
        "无法读取的设置文件，或其应用已不再安装。这台 Mac 上没有任何东西在使用它们。": "File di impostazioni illeggibili o la cui app non è più installata. Nulla su questo Mac li utilizza.",
        "指向已不存在应用的登录项，因此无法启动任何东西。": "Elementi di login che puntano ad app inesistenti, quindi incapaci di avviare alcunché.",
        "失败或被放弃的下载留下的文件。如仍需要，请重新下载。": "File residui di download falliti o abbandonati. Riscarica il file se ne hai ancora bisogno.",
        "未完成下载的部分文件和超过一天的临时文件。下载仍在进行时请勿清理。": "File parziali di download incompleti e file temporanei risalenti a oltre un giorno fa. Non pulire se un download è ancora in corso.",
        "应用在一周多以前下载的安装包。安装程序运行后就不再需要，需要时可重新下载。": "Pacchetti di installazione scaricati dalle app più di una settimana fa. Non sono più necessari dopo l'esecuzione e possono essere riscaricati.",
        "以已不再安装的应用命名的支持文件夹（每行的名称就是该应用的 ID）。以后重新安装该应用会从头开始。": "Cartelle di supporto con il nome di un'app non più installata (il nome su ciascuna riga è l'ID dell'app). Reinstallando l'app in seguito partirà da zero.",
        "你不使用的语言翻译。移除会修改应用包；如需恢复请重新安装应用。": "Traduzioni per lingue che non usi. La rimozione modifica il bundle dell'applicazione; reinstalla l'app per ripristinarle.",
        "文档的旧自动保存版本。当前版本会保留，但清理后无法再浏览旧版本。": "Versioni precedenti salvate automaticamente dei tuoi documenti. La versione attuale rimane, ma non potrai più consultare le versioni precedenti dopo la pulizia.",
        "超过 30 天的 iPhone 和 iPad 本地备份。如果这是设备唯一的备份，请保留或先备份到 iCloud。": "Backup locali di iPhone e iPad risalenti a più di 30 giorni fa. Se è l'unico backup del dispositivo, conservalo o esegui prima un backup su iCloud.",
        "从应用中移除这台 Mac 无法运行的 CPU 代码。会直接修改应用；只有重新安装才能撤销。": "Rimuove dalle applicazioni il codice per architetture CPU non eseguibili su questo Mac. Modifica direttamente le app; solo reinstallandole si annulla la modifica.",
        "DerivedData 和 Previews 会在下次构建时重建，Device Support 会在连接设备时重新复制。Archives 和模拟器数据无法重新生成；如需旧构建或崩溃符号请保留。": "DerivedData e Previews vengono ricreati alla prossima compilazione, Device Support viene ricopiato al collegamento del dispositivo. Archivi e dati dei simulatori non possono essere rigenerati; conservali se ti servono vecchie build o simboli di crash.",
        "已不在这台 Mac 上的账户的整个个人文件夹。请逐个核对名称：暂时离线的网络账户看起来完全一样。": "Intere cartelle Inizio di account non più presenti su questo Mac. Controlla ogni nome: un account di rete temporaneamente non in linea appare identico.",
        "下载文件夹中超过一周的磁盘映像，通常是已运行过的安装程序。如需要可重新下载。": "Immagini disco nei Download risalenti a oltre una settimana fa, in genere installer già eseguiti. Puoi riscaricarli se necessario.",
        "邮件保存在磁盘上的附件副本。IMAP 和 Exchange 账户可从服务器重新下载，POP 账户不行。": "Copie di allegati salvate sul disco da Mail. Per gli account IMAP ed Exchange Mail può riscaricarli dal server, ma non per gli account POP.",
        "已在废纸篓中。清倒是永久性的，无法撤销。": "Già nel Cestino. Lo svuotamento è definitivo e non può essere annullato.",
        "匹配已知恶意软件特征。如果它属于你有意安装的软件，请先检查路径。": "Corrisponde a una firma malware nota. Controlla prima il percorso se appartiene a software installato intenzionalmente.",
        "你的浏览历史和跟踪数据。清理后无法恢复；Cookie 和登录会话会保留。": "Cronologia di navigazione e dati di tracciamento. Non ripristinabili dopo la pulizia; cookie e sessioni di accesso restano.",
        "最近项目列表和类似痕迹。应用的“最近打开”菜单将会清空。": "Elenchi di elementi recenti e tracce simili. Il menu Apri recenti delle app risulterà vuoto.",
        "你自己的文件，仅按大小挑选。这里没有任何东西天生就是垃圾；请逐个检查。": "I tuoi file personali, selezionati solo per dimensione. Nulla qui è di per sé non necessario; controlla ogni singolo file.",
        "很久没打开过的你自己的文件。旧并不代表不需要；请逐个检查。": "I tuoi file personali che non apri da molto tempo. Vecchio non significa inutile; controlla ogni singolo file.",
        "逐字节完全相同的副本。每个需要的文件请至少保留一份。": "Copie identiche byte per byte. Conserva almeno una copia per ciascun file di cui hai bisogno.",
        "可能的威胁": "Possibili minacce",
        "Apple XProtect 特征：{name}": "Firma Apple XProtect: {name}",
        "在 Apple 的 Safari 扩展黑名单中：{name}": "Nella blocklist di Apple per le estensioni di Safari: {name}",
        "名称与已知家族相符：{name}": "Il nome corrisponde a una famiglia nota: {name}",
        "启动代理会运行“{name}”": "L'agente di avvio esegue «{name}»",
        "标记原因": "Perché sono stati segnalati",
        "没有可直接移除的威胁": "Nessuna minaccia che Mac Sai possa rimuovere",
        "已发现，但需要管理员才能移除": "Trovato, ma per rimuoverlo serve un amministratore",
        "这些项目位于 Mac Sai 无法修改的系统文件夹中。请在 Finder 中显示每一项，然后输入管理员密码将其移到废纸篓。": "Si trovano in cartelle di sistema che Mac Sai non può modificare. Mostra ciascuno nel Finder e spostalo nel Cestino da lì con la password di amministratore.",
        "Apple XProtect {version}：{count} 个哈希值，{blocked} 个被屏蔽的 Safari 扩展": "Apple XProtect {version}: {count} hash, {blocked} estensioni di Safari bloccate",
        "未在这台 Mac 上找到 Apple XProtect 数据": "Dati di Apple XProtect non trovati su questo Mac",
        "在黑名单上或由社区报告、但也可能是你有意安装的软件的项目。": "Corrispondenze con una blocklist o segnalate dalla community che potrebbero anche essere software installato di proposito.",
        "不会预先勾选。黑名单可能也涵盖曾经正当的软件的旧版本，社区报告也未经厂商确认，删除前请逐个核对。": "Nulla è preselezionato. Una blocklist può includere anche vecchie versioni di software un tempo legittimo e nessun produttore conferma le segnalazioni della community, quindi controlla ogni elemento prima di rimuoverlo.",
        "正在比对 XProtect 和 MalwareBazaar 哈希值...": "Confronto degli hash XProtect e MalwareBazaar...",
        "已报告至 MalwareBazaar：{name}": "Segnalato a MalwareBazaar: {name}",
        "MalwareBazaar：未启用（可在设置中添加免费的 Auth-Key）": "MalwareBazaar: disattivato (aggiungi una Auth-Key gratuita nelle Impostazioni)",
        "MalwareBazaar：{count} 个哈希值，更新于 {date}": "MalwareBazaar: {count} hash, aggiornato il {date}",
        "恶意软件数据库": "Database di malware",
        "版本 {version}：{hashes} 个哈希值，{blocked} 个被屏蔽的 Safari 扩展。由 macOS 自动更新。": "Versione {version}: {hashes} hash, {blocked} estensioni di Safari bloccate. macOS la mantiene aggiornata.",
        "可选。按下“立即更新”时，使用你免费的 abuse.ch Auth-Key 下载最近报告的 macOS 恶意软件样本哈希值。每次请求只发送你的 Auth-Key 和查询内容，绝不发送文件哈希值或路径。如果某个哈希与已签名的文件匹配，macOS 会向 Apple 查询其签名证书是否已被吊销。匹配项不会预先勾选。": "Facoltativo. Quando premi Aggiorna ora, scarica gli hash dei campioni di malware per macOS segnalati di recente con la tua Auth-Key gratuita di abuse.ch. Ogni richiesta invia solo la tua Auth-Key e la query, mai hash o percorsi di file. Se un hash corrisponde a un file firmato, macOS chiede ad Apple se il suo certificato di firma è stato revocato. Le corrispondenze non sono mai preselezionate.",
        "abuse.ch Auth-Key": "Auth-Key di abuse.ch",
        "保存密钥": "Salva chiave",
        "移除密钥和哈希值": "Rimuovi chiave e hash",
        "立即更新": "Aggiorna ora",
        "获取免费密钥": "Ottieni una chiave gratuita",
        "正在更新…": "Aggiornamento…",
        "密钥已保存在你的钥匙串中。": "Chiave salvata nel tuo portachiavi.",
        "无法将密钥保存到钥匙串。": "Impossibile salvare la chiave nel portachiavi.",
        "无法移除密钥或哈希值。": "Impossibile rimuovere la chiave o gli hash.",
        "Auth-Key 被拒绝。请在 auth.abuse.ch 检查。": "L'Auth-Key è stata rifiutata. Controllala su auth.abuse.ch.",
        "尚未下载哈希值。": "Nessun hash ancora scaricato.",
        "已更新：新增 {added} 个，共 {total} 个哈希值。": "Aggiornato: {added} nuovi, {total} hash in totale.",
        "部分查询失败：{list}": "Alcune query non sono riuscite: {list}",
        "更新失败：{list}": "Aggiornamento non riuscito: {list}",
        "无法保存下载的哈希列表。": "Impossibile salvare l'elenco di hash scaricato.",
        "服务器要求重定向，已拒绝": "il server ha chiesto un reindirizzamento, che è stato rifiutato",
        "响应过大": "la risposta era troppo grande",
        "响应格式不正确": "risposta non valida",
    ]

