        "移动受保护的项目时，macOS 可能仍会要求密码或触控 ID。完全磁盘访问权限不能代替管理员确认。Mac Sai 不保存您的密码，也不能提前批准所有操作。": "macOS puede pedir igualmente una contraseña o Touch ID al mover elementos protegidos. El acceso total al disco no sustituye la autorización del administrador. Mac Sai no guarda tu contraseña y no puede aprobar todas las operaciones por adelantado.",
