        "无法确认项目在废纸篓中的位置，请检查访达。": "No se pudo confirmar la ubicación del elemento en la Papelera. Compruébalo en el Finder.",
        "macOS 未将此项目移到废纸篓。请检查权限并重新扫描。": "macOS no movió este elemento a la Papelera. Comprueba los permisos y vuelve a analizar.",
