        "请逐项检查并选择可能的威胁和社区报告的文件。此复选框只能取消该类别中已选中的项目。": "Revisa y selecciona una por una las posibles amenazas y los archivos reportados por la comunidad. Esta casilla solo puede desmarcar los elementos seleccionados de esta categoría.",
