        "仅保留安全的临时文件、缓存、日志和残留文件。不选择个人数据、废纸篓或应用修改。": "Deja seleccionados solo archivos temporales, cachés, registros y restos seguros. No selecciona datos personales, la Papelera ni cambios en aplicaciones.",
