        "Chrome、Brave、Edge、Arc、Firefox 和 Safari 的扩展。名称与已知广告软件家族相符的会标为可疑。": "Extensiones de Chrome, Brave, Edge, Arc, Firefox y Safari. Los nombres que coinciden con familias de adware conocidas se marcan como Sospechosos.",
        "项目中已安装的依赖和构建产物。运行项目的安装或构建命令即可找回；之后第一次构建会更慢。": "Dependencias instaladas y archivos de compilación de tus proyectos. Se recuperan ejecutando el comando de instalación o compilación del proyecto; la primera compilación tardará más.",
        "无法读取 Safari 扩展列表。请在 Safari 设置 > 扩展中查看。": "No se pudo leer la lista de extensiones de Safari. Consúltala en Ajustes de Safari > Extensiones.",
        "可疑": "Sospechosa",
        "此操作不可撤销，不会进入废纸篓。": "Esto es permanente. Nada va a la Papelera.",
        "这只会忘掉恢复记录，废纸篓里的文件不会被动。之后就不能一键恢复这些清理了。": "Esto solo olvida la lista de restauración. No se toca nada en la Papelera, pero estas limpiezas ya no se pueden restaurar con un solo clic.",
        "不会自动勾选。": "No se selecciona nada automáticamente.",
        "正在查找未使用的应用…": "Buscando aplicaciones no utilizadas…",
        "6 个月": "6 meses",
        "Spotlight 没有应用的使用记录": "Spotlight no tiene historial de uso para tus aplicaciones",
        "浏览器扩展": "Extensiones del navegador",
        "支持文件": "Archivos de soporte",
        "选择项目文件夹（例如 ~/Code），查找 node_modules、venv、target、build 等可重建目录。": "Elige una carpeta de proyectos, como ~/Code, para buscar carpetas regenerables como node_modules, venv, target y build.",
        "恢复": "Restaurar",
        "正在查找项目…": "Buscando proyectos…",
        "卷": "Volúmenes",
        "3 个月": "3 meses",
        "清理只会删除悬空（无标签）镜像，带标签的镜像会保留。": "Solo se eliminan las imágenes sin etiqueta. Las imágenes etiquetadas se conservan.",
        "Firefox 正在运行，因此未删除任何内容。请在 Firefox 中通过“工具 > 附加组件和主题”移除此扩展。": "Firefox está abierto, por lo que no se eliminó nada. Elimina la extensión en Firefox desde Herramientas > Complementos y temas.",
        "删除运行时会先关闭正在使用它的模拟器，这些模拟器之后将不可用。": "Al eliminar un tiempo de ejecución, primero se cierra cualquier simulador que lo usa y esos simuladores dejan de estar disponibles.",
        "在 Chrome、Brave、Edge、Arc、Firefox 或 Safari 中未找到扩展": "No se encontraron extensiones en Chrome, Brave, Edge, Arc, Firefox o Safari",
        "没有符合条件的应用": "No hay aplicaciones sin usar en este período",
        "已从废纸篓清空：%ld": "Ya eliminados de la Papelera: %ld",
        "此扩展由管理策略安装，删除文件夹后 {browser} 会重新安装它。如果你不认识它，请在系统设置中搜索“描述文件”或“设备管理”，并移除你不认识的描述文件。": "Esta extensión la instaló una política de administración, así que {browser} la volvería a instalar. Si no la reconoces, busca Perfiles o Gestión de dispositivos en Ajustes del Sistema y elimina cualquier perfil que no reconozcas.",
        "卸载…": "Desinstalar…",
        "已将扩展移到废纸篓。": "La extensión fue movida a la Papelera.",
        "永久清理所选 Docker 项目？": "¿Eliminar permanentemente los elementos de Docker seleccionados?",
        "已恢复：%ld": "Restaurados: %ld",
        "构建缓存": "Caché de compilación",
        "Xcode 模拟器": "Simuladores Xcode",
        "%ld 项": "%ld elementos",
        "清除历史": "Borrar historial",
        "清除清理历史？": "¿Borrar el historial de limpieza?",
        "上次打开": "Abierto por última vez",
        "未找到项目垃圾": "No se encontró basura de proyectos",
        "Chrome 正在运行，因此未删除任何内容。请在 Chrome 中通过“窗口 > 扩展程序”移除此扩展。": "Chrome está abierto, por lo que no se eliminó nada. Elimina la extensión en Chrome desde Ventana > Extensiones.",
        "项目垃圾": "Basura de proyectos",
        "内置": "Integrada",
        "重复文件检测会使用 SHA-256 哈希每个候选文件。\n大型个人目录可能需要 5–15 分钟。": "La detección de duplicados calcula el hash SHA-256 de cada archivo candidato.\nLas carpetas de inicio grandes pueden tardar entre 5 y 15 minutos.",
        "清理历史": "Historial de limpieza",
        "删除完成": "Eliminado",
        "正在计算文件夹大小…": "Calculando el tamaño de las carpetas…",
        "还没有可恢复的清理记录": "Aún no hay limpiezas que restaurar",
        "已找到 Docker，但它没有响应。请先启动 Docker Desktop，然后点“刷新”。": "Docker está instalado pero no responde. Abre Docker Desktop y luego haz clic en Actualizar.",
        "永久删除所选模拟器项目？": "¿Eliminar permanentemente los elementos del simulador seleccionados?",
        "移除扩展？": "¿Quitar extensión?",
        "永久清理": "Eliminar permanentemente",
        "按上次打开时间列出应用，并按占用空间排序。一键转到卸载器。": "Aplicaciones que no has abierto recientemente, ordenadas según el espacio que usan. Un clic las envía al Desinstalador.",
        "正在读取扩展…": "Leyendo extensiones…",
        "原位置已有文件，已跳过：%ld": "Omitidos porque la ubicación original está ocupada: %ld",
        "扫描 Mac 中的垃圾文件、恶意威胁\n和性能问题": "Analiza tu Mac en busca de archivos innecesarios,\namenazas de malware y problemas de rendimiento",
        "此扩展内置于 {browser}，无法移除。": "Esta extensión está integrada en {browser} y no se puede eliminar.",
        "未使用的应用": "Aplicaciones sin usar",
        "名称与已知广告软件家族相符。这只是提示，并非确认。": "El nombre coincide con una conocida familia de adware. Esto es una pista, no una detección confirmada.",
        "未找到 Docker": "Docker no encontrado",
        "卷可能保存着数据库等数据，Mac Sai 不会清理它们。如需删除，请使用 Docker Desktop 或 Docker 命令行。": "Los volúmenes pueden contener datos de bases de datos, por lo que Mac Sai los deja en paz. Para eliminarlos, usa Docker Desktop o Docker CLI.",
        "不可用的模拟器": "Simulador no disponible",
        "后台": "En segundo plano",
        "这次清理，你没花一分钱。": "Esa limpieza no te costó nada.",
        "没有订阅，没有广告，没有追踪。Mac Sai 是我和几位志愿者在业余时间做的。如果它帮你省下了买清理软件的钱，请我喝杯咖啡，让它对所有人继续免费。": "Sin suscripciones, anuncios ni seguimiento. Desarrollo Mac Sai por las noches y los fines de semana con unos voluntarios. Si te ahorró pagar por una aplicación de limpieza, un café ayuda a mantenerlo gratis para todos.",
        "请我喝杯咖啡": "Invítame a un café",
        "以后再说": "Quizá más tarde",
        "不再提示": "No volver a preguntar",
        "谢谢你。正因为有你，它才能一直免费。": "Gracias. Tú eres la razón por la que sigue siendo gratuito.",
        "支持 Mac Sai": "Apoyar a Mac Sai",
        "支持者": "Colaboradores",
        "感谢你们让 Mac Sai 保持免费：{names}。": "Gracias por mantener Mac Sai gratis: {names}.",
        "支持 Mac Sai 的会员会列在这里。来做第一个吧。": "Aquí aparecen los miembros que mantienen Mac Sai gratis. Sé el primero.",
        "成为会员，或请开发者喝杯咖啡": "Hazte miembro o invita a un café al desarrollador",
        "1 - 3 个月": "1 - 3 meses",
        "3 - 6 个月": "3 - 6 meses",
        "30 天内不再显示": "Ocultar durante 30 días",
        "6 个月 - 1 年": "6 meses - 1 año",
        "AI 工具缓存": "Cachés de herramientas de IA",
        "AI 编码工具的缓存（Claude、Codex）；不含历史与会话。": "Cachés de herramientas de codificación de IA (Claude, Codex). Historia y sesiones excluidas.",
        "CPU": "CPU",
        "GPU 使用率": "Uso de GPU",
        "GitHub 返回了无法识别的响应。": "Respuesta inesperada de GitHub.",
        "Homebrew 返回了无法识别的响应。": "Respuesta inesperada de Homebrew.",
        "IDE 与编辑器缓存": "Cachés de IDE y editor",
        "Internet 插件": "Complementos de Internet",
        "PDF": "PDF",
        "Safari 扩展": "Extensiones de Safari",
        "Safari 扩展不能在本应用内开启、关闭或删除，以免破坏宿主应用的签名。请在 Safari 设置中管理它们。": "Las extensiones de Safari no se pueden activar, desactivar ni eliminar aquí; eso rompería la firma de la aplicación anfitriona. Gestiónalas en los ajustes de Safari.",
        "Spotlight 的整个搜索索引会被清除并重建。数小时内 Spotlight 搜索可能返回空结果（主目录越大耗时越久），系统搜索和智能文件夹也会受影响。": "Todo el índice de búsqueda de Spotlight se borra y se reconstruye. La búsqueda de Spotlight arrojará resultados vacíos durante varias horas (más tiempo para directorios personales grandes). La búsqueda del sistema y las carpetas inteligentes también se ven afectadas.",
        "URL Scheme": "Esquema de URL",
        "Xcode 垃圾": "Basura de Xcode",
        "iOS 设备备份": "Copias de seguridad de dispositivos iOS",
        "iPhone 和 iPad 的本地备份。": "Copias de seguridad locales de dispositivos iPhone y iPad.",
        "macOS 的“哪类文件由哪个应用打开”数据库会被清除并重建。完成前（通常数小时），双击文件可能失败或打开错误应用，默认应用设置可能重置，Spotlight 启动应用也可能不可用。重启可加快恢复。": "La base de datos de macOS de \"qué aplicación abre qué tipo de archivo\" se borra y se reconstruye. Hasta que finalice (a menudo varias horas), es posible que no se pueda hacer doble clic en los archivos o que se abra la aplicación incorrecta, que se restablezca la configuración predeterminada de la aplicación y que no funcione el inicio de aplicaciones a través de Spotlight. Un reinicio acelera esto.",
        "macOS 诊断日志。": "Registros de diagnóstico de macOS.",
        "npm、Cargo、pip、Homebrew、Gradle 的可重建缓存。": "Cachés regenerables de npm, Cargo, pip, Homebrew y Gradle.",
        "~/Library/Logs/MacClean/operations.log — 30 天后自动清理": "~/Library/Logs/MacClean/operations.log: se depura a los 30 días",
        "“邮件”应用的搜索索引会从头重建。重建完成前，邮件搜索和未读数可能不准确（大型邮箱通常需 10–30 分钟）。": "El índice de búsqueda de Mail.app se reconstruye desde cero. La búsqueda de correo y los recuentos de no leídos serán incorrectos hasta que finalice la reconstrucción (normalmente entre 10 y 30 minutos en un buzón grande).",
        "一切就绪！": "¡Ya estás listo!",
