        "主题": "Tema",
        "仅显示错误": "Solo errores",
        "仅移除 macOS 已标记可清理的 Time Machine 本地快照；不会删除你主动需要的内容。": "Solo se eliminan las instantáneas locales de Time Machine que macOS ya marcó como eliminables; no se elimina nada que necesites.",
