        "以开源方式让你的 Mac 保持干净、快速和安全。": "La forma de código abierto de mantener tu Mac limpio, rápido y seguro.",
        "优化": "Optimización",
        "优化你的 Mac": "Optimiza tu Mac",
        "会产生几分钟磁盘活动。该操作为只读，无论结果如何都不会更改磁盘内容。": "Unos minutos de actividad del disco. Solo lectura: no se cambia nada en el disco independientemente del resultado.",
        "会删除本地 Time Machine 快照以释放空间。远程或备份盘上的快照不受影响，你仍可从 Time Machine 备份恢复。": "Las instantáneas locales de Time Machine se eliminan para liberar espacio en disco. Las instantáneas de discos remotos o de copia de seguridad no se ven afectadas; aún puedes restaurar desde la propia copia de seguridad de Time Machine.",
        "你的 Mac 很干净！": "¡Tu Mac está limpio!",
        "你选择的项目已在废纸篓中——需要时可以恢复。若要彻底删除，请打开“废纸篓”模块并清空。": "Los elementos seleccionados están en la Papelera: recupera lo que necesites. Para borrarlos definitivamente, abre Papeleras y vacíala.",
