        "清理前请检查": "Revisar antes de limpiar",
        "应用临时文件。每个应用下次启动时会自动重新生成。": "Archivos temporales de la aplicación. Se recrea automáticamente la próxima vez que se inicia cada aplicación.",
        "由 macOS 自行管理的缓存，需要时会自动重建。": "Cachés que gestiona macOS. Se regeneran automáticamente cuando hace falta.",
        "下载和构建缓存。npm、Cargo、pip、Homebrew 和 Gradle 会在下次安装或构建时重新下载所需内容。": "Cachés de descargas y compilación. npm, Cargo, pip, Homebrew y Gradle vuelven a descargar lo necesario en la próxima instalación o compilación.",
        "仅编辑器缓存。Cursor 和 Antigravity 下次启动时会重新生成；你的设置和扩展不受影响。": "Solo cachés del editor. Cursor y Antigravity los recrean en el próximo lanzamiento; tu configuración y extensiones no se modifican.",
        "仅临时和缓存文件夹。Claude 和 Codex 会按需重新生成；绝不包含历史、记忆和会话。": "Solo carpetas temporales y de caché. Claude y Codex las recrean cuando hace falta; nunca se incluyen el historial, la memoria ni las sesiones.",
        "应用为排查问题写下的诊断记录。应用不会回读旧日志，运行时会写新的日志。": "Texto de diagnóstico que escribieron tus aplicaciones para solucionar problemas. Las aplicaciones no leen los registros antiguos e inician otros nuevos a medida que se ejecutan.",
        "macOS 诊断日志。仅在排查过去的问题时有用；macOS 会继续写入新日志。": "Registros de diagnóstico de macOS. Solo es útil cuando se investiga un problema pasado; macOS sigue escribiendo nuevos.",
        "无法读取的设置文件，或其应用已不再安装。这台 Mac 上没有任何东西在使用它们。": "Archivos de configuración que no se pueden leer o cuya aplicación ya no está instalada. Nada en este Mac los usa.",
        "指向已不存在应用的登录项，因此无法启动任何东西。": "Entradas de inicio de sesión que apuntan a aplicaciones que ya no existen, por lo que no pueden iniciar nada.",
        "失败或被放弃的下载留下的文件。如仍需要，请重新下载。": "Restos de descargas que fallaron o fueron abandonadas. Descarga el archivo nuevamente si aún lo quieres.",
        "未完成下载的部分文件和超过一天的临时文件。下载仍在进行时请勿清理。": "Archivos parciales de descargas inacabadas y archivos temporales de hace un día. No limpies mientras aún se esté ejecutando una descarga.",
        "应用在一周多以前下载的安装包。安装程序运行后就不再需要，需要时可重新下载。": "Paquetes de instalación que las aplicaciones descargaron hace más de una semana. Ya no se necesitan una vez ejecutados y se pueden descargar de nuevo.",
        "以已不再安装的应用命名的支持文件夹（每行的名称就是该应用的 ID）。以后重新安装该应用会从头开始。": "Carpetas de soporte de aplicaciones que ya no están instaladas. Cada fila muestra el identificador de la aplicación. Si la reinstalas, empezará desde cero.",
        "你不使用的语言翻译。移除会修改应用包；如需恢复请重新安装应用。": "Traducciones de idiomas que no usas. Eliminarlas modifica el paquete de la aplicación; reinstálala para recuperarlas.",
        "文档的旧自动保存版本。当前版本会保留，但清理后无法再浏览旧版本。": "Revisiones antiguas guardadas automáticamente de tus documentos. La versión actual permanece, pero las más antiguas no se pueden explorar después de limpiarlas.",
        "超过 30 天的 iPhone 和 iPad 本地备份。如果这是设备唯一的备份，请保留或先备份到 iCloud。": "Copias de seguridad locales de iPhone y iPad con más de 30 días. Si es la única copia de seguridad de un dispositivo, consérvala o haz una copia de seguridad primero en iCloud.",
        "从应用中移除这台 Mac 无法运行的 CPU 代码。会直接修改应用；只有重新安装才能撤销。": "Elimina de las aplicaciones el código de CPU que este Mac no puede ejecutar. Modifica las aplicaciones instaladas; solo reinstalarlas revierte el cambio.",
        "DerivedData 和 Previews 会在下次构建时重建，Device Support 会在连接设备时重新复制。Archives 和模拟器数据无法重新生成；如需旧构建或崩溃符号请保留。": "DerivedData y Previews se regeneran en la próxima compilación; Device Support se copia de nuevo al conectar un dispositivo. Los archivos de compilaciones y los datos del simulador no se pueden regenerar: consérvalos si necesitas compilaciones antiguas o símbolos de fallos.",
        "已不在这台 Mac 上的账户的整个个人文件夹。请逐个核对名称：暂时离线的网络账户看起来完全一样。": "Carpetas de inicio completas de cuentas que ya no existen en este Mac. Revisa cada nombre: una cuenta de red temporalmente desconectada puede parecer igual.",
        "下载文件夹中超过一周的磁盘映像，通常是已运行过的安装程序。如需要可重新下载。": "Imágenes de disco en Descargas de más de una semana, normalmente instaladores que ya se ejecutaron. Descárgalos nuevamente si los necesitas.",
        "邮件保存在磁盘上的附件副本。IMAP 和 Exchange 账户可从服务器重新下载，POP 账户不行。": "Copias de adjuntos que Mail guardó en el disco. Mail puede volver a descargarlas del servidor para cuentas IMAP y Exchange, pero no para POP.",
        "已在废纸篓中。清倒是永久性的，无法撤销。": "Ya en la Papelera. Vaciarlo es permanente y no se puede deshacer.",
        "匹配已知恶意软件特征。如果它属于你有意安装的软件，请先检查路径。": "Coincide con una firma de malware conocida. Si pertenece a software que instalaste a propósito, revisa primero la ruta.",
        "你的浏览历史和跟踪数据。清理后无法恢复；Cookie 和登录会话会保留。": "Tu historial de navegación y datos de seguimiento. No se puede restaurar después de la limpieza; las cookies y las sesiones iniciadas se conservan.",
        "最近项目列表和类似痕迹。应用的“最近打开”菜单将会清空。": "Listas de elementos recientes y rastros similares. Los menús Abrir recientes de las aplicaciones quedarán vacíos.",
        "你自己的文件，仅按大小挑选。这里没有任何东西天生就是垃圾；请逐个检查。": "Tus propios archivos, seleccionados solo por tamaño. Nada aquí es basura por definición; revisa cada uno.",
        "很久没打开过的你自己的文件。旧并不代表不需要；请逐个检查。": "Tus propios archivos que no has abierto en mucho tiempo. Viejo no significa innecesario; revisa cada uno.",
        "逐字节完全相同的副本。每个需要的文件请至少保留一份。": "Copias idénticas byte por byte. Guarda al menos una copia de cada archivo que necesites.",
        "可能的威胁": "Posibles amenazas",
        "Apple XProtect 特征：{name}": "Firma de Apple XProtect: {name}",
        "在 Apple 的 Safari 扩展黑名单中：{name}": "En la lista de bloqueo de Apple para extensiones de Safari: {name}",
        "名称与已知家族相符：{name}": "El nombre coincide con una familia conocida: {name}",
        "启动代理会运行“{name}”": "El agente de inicio ejecuta «{name}»",
        "标记原因": "Por qué se marcaron",
        "没有可直接移除的威胁": "No hay amenazas que Mac Sai pueda eliminar",
        "已发现，但需要管理员才能移除": "Encontrado, pero se necesita un administrador para eliminarlo",
        "这些项目位于 Mac Sai 无法修改的系统文件夹中。请在 Finder 中显示每一项，然后输入管理员密码将其移到废纸篓。": "Estos elementos están en carpetas del sistema que Mac Sai no puede modificar. Muestra cada uno en el Finder y muévelo a la Papelera desde allí con la contraseña de administrador.",
        "Apple XProtect {version}：{count} 个哈希值，{blocked} 个被屏蔽的 Safari 扩展": "Apple XProtect {version}: {count} hashes, {blocked} extensiones de Safari bloqueadas",
        "未在这台 Mac 上找到 Apple XProtect 数据": "No se encontraron datos de Apple XProtect en este Mac",
        "在黑名单上或由社区报告、但也可能是你有意安装的软件的项目。": "Coincidencias con una lista de bloqueo o reportadas por la comunidad que también podrían ser software que instalaste a propósito.",
        "不会预先勾选。黑名单可能也涵盖曾经正当的软件的旧版本，社区报告也未经厂商确认，删除前请逐个核对。": "No se preselecciona nada. Una lista de bloqueo puede incluir versiones antiguas de software que antes era legítimo y ningún fabricante confirma los reportes de la comunidad, así que revisa cada elemento antes de eliminarlo.",
        "正在比对 XProtect 和 MalwareBazaar 哈希值...": "Comparando hashes de XProtect y MalwareBazaar...",
        "已报告至 MalwareBazaar：{name}": "Reportado a MalwareBazaar: {name}",
        "MalwareBazaar：未启用（可在设置中添加免费的 Auth-Key）": "MalwareBazaar: desactivado (añade una Auth-Key gratuita en Ajustes)",
        "MalwareBazaar：{count} 个哈希值，更新于 {date}": "MalwareBazaar: {count} hashes, actualizado el {date}",
        "恶意软件数据库": "Base de datos de malware",
        "版本 {version}：{hashes} 个哈希值，{blocked} 个被屏蔽的 Safari 扩展。由 macOS 自动更新。": "Versión {version}: {hashes} hashes, {blocked} extensiones de Safari bloqueadas. macOS la mantiene actualizada.",
        "可选。按下“立即更新”时，使用你免费的 abuse.ch Auth-Key 下载最近报告的 macOS 恶意软件样本哈希值。每次请求只发送你的 Auth-Key 和查询内容，绝不发送文件哈希值或路径。如果某个哈希与已签名的文件匹配，macOS 会向 Apple 查询其签名证书是否已被吊销。匹配项不会预先勾选。": "Opcional. Al pulsar Actualizar ahora, se descargan los hashes de muestras de malware para macOS reportadas recientemente con tu Auth-Key gratuita de abuse.ch. Cada solicitud envía solo tu Auth-Key y la consulta, nunca hashes ni rutas de archivos. Si un hash coincide con un archivo firmado, macOS pregunta a Apple si su certificado de firma se ha revocado. Las coincidencias nunca se preseleccionan.",
        "abuse.ch Auth-Key": "Auth-Key de abuse.ch",
        "保存密钥": "Guardar clave",
        "移除密钥和哈希值": "Eliminar clave y hashes",
        "立即更新": "Actualizar ahora",
        "获取免费密钥": "Obtener una clave gratuita",
        "正在更新…": "Actualizando…",
        "密钥已保存在你的钥匙串中。": "Clave guardada en tu llavero.",
        "无法将密钥保存到钥匙串。": "No se pudo guardar la clave en el llavero.",
        "无法移除密钥或哈希值。": "No se pudo eliminar la clave o los hashes.",
        "Auth-Key 被拒绝。请在 auth.abuse.ch 检查。": "Se rechazó la Auth-Key. Compruébala en auth.abuse.ch.",
        "尚未下载哈希值。": "Aún no se han descargado hashes.",
        "已更新：新增 {added} 个，共 {total} 个哈希值。": "Actualizado: {added} nuevos, {total} hashes en total.",
        "部分查询失败：{list}": "Algunas consultas fallaron: {list}",
