        "等待并退出": "完了を待って終了",
        "留在应用中": "アプリの使用を続ける",
        "暂时无法退出": "まだ終了できません",
        "清理权限": "クリーンアップの権限",
        "允许 Mac Sai 扫描邮件、浏览器数据和其他受保护的文件夹。在系统设置中添加 Mac Sai 并开启权限，然后重新启动应用并重新扫描。": "Mac Sai がメール、ブラウザのデータ、その他の保護されたフォルダをスキャンできるようにします。システム設定で Mac Sai を追加してアクセスを許可したあと、アプリを再起動してもう一度スキャンしてください。",
        "打开完全磁盘访问设置": "フルディスクアクセスの設定を開く",
        "管理员确认": "管理者による承認",
        "移动受保护的项目时，macOS 可能仍会要求密码或触控 ID。完全磁盘访问权限不能代替管理员确认。Mac Sai 不保存您的密码，也不能提前批准所有操作。": "保護された項目を移動するとき、macOS がパスワードや Touch ID を求めることがあります。フルディスクアクセスは管理者による承認の代わりにはなりません。Mac Sai はパスワードを保存せず、すべての操作を事前に承認することもできません。",
        "批量移到废纸篓": "まとめてゴミ箱に移動",
        "清理会将选中的项目分组交给 macOS，减少逐项请求。系统决定是否需要再次确认。取消后，当前组会先完成；已移动的项目仍会显示在清理历史中。": "クリーンアップでは、個別の要求を減らすため、選択した項目をグループ単位で macOS に渡します。追加の承認が必要かどうかはシステムが判断します。キャンセルした場合は現在のグループが先に完了し、移動済みの項目はクリーンアップ履歴に残ります。",
        "权限": "権限",
        "另一项清理仍在进行中。": "別のクリーンアップがまだ実行中です。",
        "准备清理时文件已更改，请重新扫描。": "クリーンアップの準備中に項目が変更されました。もう一度スキャンしてください。",
        "无法确认项目在废纸篓中的位置，请检查访达。": "ゴミ箱内の項目の場所を確認できませんでした。Finder で確認してください。",
        "macOS 未将此项目移到废纸篓。请检查权限并重新扫描。": "macOS はこの項目をゴミ箱に移動しませんでした。権限を確認して、もう一度スキャンしてください。",
        "符号链接改变了清理路径。请在访达中检查。": "シンボリックリンクによってクリーンアップのパスが変わりました。Finder で項目を確認してください。",
