        "请逐项检查并选择可能的威胁和社区报告的文件。此复选框只能取消该类别中已选中的项目。": "可能性のある脅威とコミュニティから報告されたファイルは、1つずつ確認して選択してください。このチェックボックスでは、このカテゴリで選択済みの項目の選択解除のみ行えます。",
