        "内存压力持续偏高时通知你。": "メモリプレッシャーが高い状態が続くと通知します。",
        "交换空间提醒": "スワップ使用量のアラート",
        "交换空间超过所选大小时通知一次，降到明显低于该值后才会再次提醒。": "スワップが選択したサイズを超えると1回通知し、その値を十分に下回るまで再度通知しません。",
        "不提醒": "オフ",
        "提醒由菜单栏小组件发送，需要保持开启。": "アラートはメニューバーのウィジェットから送信されるため、ウィジェットをオンのままにしておく必要があります。",
        "交换空间 {size}": "スワップ {size}",
        "交换空间使用过高": "スワップ使用量が多い",
        "你的 Mac 正在使用 {used} 交换空间，超过了你设置的 {limit} 提醒值。退出不用的应用可以减轻内存压力。": "お使いの Mac は {used} のスワップを使用しており、設定したアラートのしきい値 {limit} を超えています。使っていないアプリを終了すると、メモリプレッシャーを軽減できます。",
        "查找并移除系统缓存、日志、\n语言文件和其他垃圾": "システムキャッシュ、ログ、言語ファイルなどの\n不要ファイルを検索して削除します",
        "清理会删除悬空的构建缓存。下次构建可能会变慢。": "孤立したビルドキャッシュを削除します。次回のビルドは時間がかかる場合があります。",
        "代码项目中的依赖和构建文件夹。": "コードプロジェクト内の依存関係とビルドフォルダ。",
        "每一项都会放回原位置。原位置已有的文件绝不会被覆盖。": "各項目は元の場所に戻ります。その場所にすでにあるファイルが上書きされることはありません。",
        "Mac Sai 无法确认此扩展的文件夹可以安全移除，因此未删除任何内容。": "この拡張機能のフォルダを安全に削除できることを Mac Sai が確認できなかったため、何も削除されませんでした。",
        "无法移到废纸篓：": "ゴミ箱に移動できませんでした: ",
        "恢复这次清理？": "このクリーンアップを元に戻しますか？",
        "恢复完成": "復元が完了しました",
        "详情": "詳細",
        "时间": "期間",
        "无法恢复：%ld": "復元できませんでした: %ld",
        "这次清理太大，只能恢复前 %ld 项。其余 %ld 项仍在废纸篓中，可在访达里手动放回。": "このクリーンアップは大きすぎてすべてを記録できませんでした。復元できるのは最初の %ld 項目のみです。残りの %ld 項目はゴミ箱に残っているため、Finder から戻すことができます。",
        "如果 {browser} 已关闭，扩展文件夹会移到废纸篓。如果它正在运行，则不会删除任何内容，并会告诉你在哪里移除。如果你开启了 {browser} 同步，它可能会重新安装此扩展。": "{browser} が終了している場合、拡張機能のフォルダをゴミ箱に移動します。起動中の場合は何も削除せず、削除方法を表示します。{browser} の同期により拡張機能が再インストールされることがあります。",
        "镜像": "イメージ",
        "清除": "クリア",
        "部分可恢复": "一部を復元可能",
        "由策略安装": "ポリシーによりインストール",
        "清理所选 Docker 项目…": "選択した Docker 項目を削除…",
        "清理完成": "クリーンアップ完了",
        "{browser} 正在运行，因此未删除任何内容。请在 {browser} 的地址栏中打开 {url} 来移除此扩展。": "{browser} が開いているため、何も削除されませんでした。アドレスバーで {url} を開き、{browser} から拡張機能を削除してください。",
        "在设置中打开": "設定で開く",
        "已停止": "停止しました",
        "开发者磁盘占用": "開発用ストレージ",
        "无法判断哪些应用未被使用。请检查 Spotlight 索引是否已开启。": "Mac Sai は未使用のアプリを判別できません。Spotlight のインデックス作成が有効か確認してください。",
        "未知日期": "日付不明",
        "把最近一次清理整批恢复到原位置。已清空废纸篓或原路径已有文件的项会被跳过。": "1回分のクリーンアップをワンクリックでまとめて元に戻します。ゴミ箱からすでに削除された項目や、元の場所に新しいファイルがある項目はスキップされます。",
        "旧版运行时": "古いランタイム",
        "12 个月": "12ヶ月",
        "删除所选模拟器项目…": "選択したシミュレータ項目を削除…",
        "未能完成": "失敗しました",
        "这台 Mac 上没有找到 Docker 或 Xcode 模拟器。": "この Mac に Docker または Xcode シミュレータが見つかりません。",
        "Safari 扩展随 App 一起安装，由 macOS 管理，因此此列表只读。将改为打开“设置”。": "Safari 拡張機能はアプリに付属し macOS が管理しているため、この一覧は読み取り専用です。代わりに設定が開きます。",
        "超时，已停止": "タイムアウトしたため停止しました",
        "关于此扩展": "この拡張機能について",
        "清理会永久删除所有已停止的容器及其中的数据。正在运行的容器不受影响。": "停止中のすべてのコンテナとそのデータを完全に削除します。実行中のコンテナには影響しません。",
        "Docker 和 Xcode 模拟器占用的空间。只显示在这台 Mac 上找到的工具，且不会自动勾选任何项目。": "Docker と Xcode シミュレータが使用している領域。この Mac にあるツールのみが表示され、何も事前に選択されません。",
        "容器": "コンテナ",
        "使用渐进式 SHA-256 哈希检测\n查找重复文件": "段階的な SHA-256 ハッシュ検証で\n重複ファイルを検索します",
        "请选择你的项目文件夹，而不是系统文件夹或资源库。": "システムフォルダやライブラリではなく、プロジェクトのフォルダを選択してください。",
        "Chrome、Brave、Edge、Arc、Firefox 和 Safari 的扩展。名称与已知广告软件家族相符的会标为可疑。": "Chrome、Brave、Edge、Arc、Firefox、Safari の拡張機能。既知のアドウェアファミリーと一致する名前には「不審」と表示されます。",
        "项目中已安装的依赖和构建产物。运行项目的安装或构建命令即可找回；之后第一次构建会更慢。": "プロジェクト内のインストール済みの依存関係とビルド出力です。インストールやビルドのコマンドで再作成できますが、初回のビルドは時間がかかります。",
        "无法读取 Safari 扩展列表。请在 Safari 设置 > 扩展中查看。": "Safari 拡張機能の一覧を読み取れませんでした。代わりに Safari の設定の「拡張機能」を確認してください。",
        "可疑": "不審",
        "此操作不可撤销，不会进入废纸篓。": "この操作は元に戻せません。ゴミ箱には移動されず、完全に削除されます。",
        "这只会忘掉恢复记录，废纸篓里的文件不会被动。之后就不能一键恢复这些清理了。": "復元リストを消去するだけです。ゴミ箱の中身はそのまま残りますが、これらのクリーンアップはワンクリックで復元できなくなります。",
        "不会自动勾选。": "何も自動選択されません。",
        "正在查找未使用的应用…": "使用していないアプリを探しています…",
        "6 个月": "6ヶ月",
        "Spotlight 没有应用的使用记录": "Spotlight にはアプリの使用履歴がありません",
        "浏览器扩展": "ブラウザ拡張機能",
        "支持文件": "サポートファイル",
        "选择项目文件夹（例如 ~/Code），查找 node_modules、venv、target、build 等可重建目录。": "~/Code などのプロジェクトフォルダを選択し、node_modules、venv、target、build などの再作成可能なフォルダを検索します。",
        "恢复": "復元",
        "正在查找项目…": "プロジェクトを検索中…",
        "卷": "ボリューム",
        "3 个月": "3ヶ月",
        "清理只会删除悬空（无标签）镜像，带标签的镜像会保留。": "タグのないイメージだけを削除します。タグ付きイメージは保持されます。",
        "Firefox 正在运行，因此未删除任何内容。请在 Firefox 中通过“工具 > 附加组件和主题”移除此扩展。": "Firefox が開いているため、何も削除されませんでした。Firefox の「ツール」>「アドオンとテーマ」から拡張機能を削除してください。",
        "删除运行时会先关闭正在使用它的模拟器，这些模拟器之后将不可用。": "ランタイムを削除すると、それを使用しているシミュレータはシャットダウンされ、使用できなくなります。",
        "在 Chrome、Brave、Edge、Arc、Firefox 或 Safari 中未找到扩展": "Chrome、Brave、Edge、Arc、Firefox、Safari に拡張機能が見つかりません",
        "没有符合条件的应用": "この期間に該当する未使用アプリはありません",
        "已从废纸篓清空：%ld": "ゴミ箱から削除済み: %ld",
        "此扩展由管理策略安装，删除文件夹后 {browser} 会重新安装它。如果你不认识它，请在系统设置中搜索“描述文件”或“设备管理”，并移除你不认识的描述文件。": "この拡張機能は管理ポリシーによってインストールされたため、{browser} が再インストールします。心当たりがない場合は、システム設定で「プロファイル」または「デバイス管理」を検索し、見覚えのないプロファイルを削除してください。",
        "卸载…": "アンインストール…",
        "已将扩展移到废纸篓。": "拡張機能はゴミ箱に移動されました。",
        "永久清理所选 Docker 项目？": "選択した Docker 項目を完全に削除しますか？",
        "已恢复：%ld": "復元済み: %ld",
        "构建缓存": "ビルドキャッシュ",
        "Xcode 模拟器": "Xcode シミュレータ",
        "%ld 项": "%ld 件",
        "清除历史": "履歴を消去",
        "清除清理历史？": "クリーンアップ履歴を消去しますか？",
        "上次打开": "最後に開いた",
        "未找到项目垃圾": "プロジェクトの不要ファイルは見つかりませんでした",
        "Chrome 正在运行，因此未删除任何内容。请在 Chrome 中通过“窗口 > 扩展程序”移除此扩展。": "Chrome が開いているため、何も削除されませんでした。Chrome の「ウィンドウ」>「拡張機能」から拡張機能を削除してください。",
        "项目垃圾": "プロジェクトの不要ファイル",
        "内置": "内蔵",
        "重复文件检测会使用 SHA-256 哈希每个候选文件。\n大型个人目录可能需要 5–15 分钟。": "重複の検出では、候補ファイルごとに SHA-256 ハッシュを計算します。\nホームフォルダが大きい場合は5～15分かかることがあります。",
        "清理历史": "クリーンアップ履歴",
        "删除完成": "削除されました",
        "正在计算文件夹大小…": "フォルダサイズを計算中…",
        "还没有可恢复的清理记录": "復元できるクリーンアップはまだありません",
        "已找到 Docker，但它没有响应。请先启动 Docker Desktop，然后点“刷新”。": "Docker はインストールされていますが、応答しません。Docker Desktop を起動して「更新」をクリックしてください。",
        "永久删除所选模拟器项目？": "選択したシミュレータ項目を完全に削除しますか？",
        "移除扩展？": "拡張機能を削除しますか？",
        "永久清理": "完全に削除",
        "按上次打开时间列出应用，并按占用空间排序。一键转到卸载器。": "最近開いていないアプリを使用容量順に表示します。ワンクリックでアンインストーラーに送れます。",
        "正在读取扩展…": "拡張機能を読み込み中…",
        "原位置已有文件，已跳过：%ld": "元の場所にファイルがあるためスキップ: %ld",
        "扫描 Mac 中的垃圾文件、恶意威胁\n和性能问题": "Mac の不要ファイル、マルウェアの脅威、\nパフォーマンスの問題をスキャンします",
        "此扩展内置于 {browser}，无法移除。": "この拡張機能は {browser} に組み込まれており、削除できません。",
        "未使用的应用": "未使用のアプリ",
        "名称与已知广告软件家族相符。这只是提示，并非确认。": "この名前は既知のアドウェアファミリーと一致します。これは注意喚起であり、検出が確定したものではありません。",
        "未找到 Docker": "Docker が見つかりません",
        "卷可能保存着数据库等数据，Mac Sai 不会清理它们。如需删除，请使用 Docker Desktop 或 Docker 命令行。": "ボリュームにはデータベースなどの永続データが含まれることがあるため、Mac Sai は削除しません。削除するには Docker Desktop または docker コマンドを使用してください。",
        "不可用的模拟器": "利用できないシミュレータ",
        "后台": "バックグラウンド",
        "这次清理，你没花一分钱。": "このクリーンアップにお金はかかっていません。",
        "没有订阅，没有广告，没有追踪。Mac Sai 是我和几位志愿者在业余时间做的。如果它帮你省下了买清理软件的钱，请我喝杯咖啡，让它对所有人继续免费。": "サブスクリプションも広告も追跡もありません。数人のボランティアと夜や週末に Mac Sai を開発しています。有料のクリーナーアプリを買わずに済んだなら、コーヒー1杯分の支援で、誰でも無料で使い続けられます。",
        "请我喝杯咖啡": "コーヒーをおごる",
        "以后再说": "後で",
        "不再提示": "今後表示しない",
        "谢谢你。正因为有你，它才能一直免费。": "ありがとうございます。皆さまのおかげで無料で提供し続けられます。",
        "支持 Mac Sai": "Mac Sai を支援",
        "支持者": "サポーター",
        "感谢你们让 Mac Sai 保持免费：{names}。": "Mac Sai の無料提供を支えてくださる皆さんに感謝します：{names}",
        "支持 Mac Sai 的会员会列在这里。来做第一个吧。": "Mac Sai を支えるメンバーがここに表示されます。最初のメンバーになりませんか？",
        "成为会员，或请开发者喝杯咖啡": "メンバーになる、または開発者にコーヒーをおごる",
        "1 - 3 个月": "1～3ヶ月",
        "3 - 6 个月": "3～6ヶ月",
        "30 天内不再显示": "30日間表示しない",
        "6 个月 - 1 年": "6ヶ月～1年",
        "AI 工具缓存": "AI ツールのキャッシュ",
        "AI 编码工具的缓存（Claude、Codex）；不含历史与会话。": "AI コーディングツール（Claude、Codex）のキャッシュ。履歴とセッションは除外されます。",
        "CPU": "CPU",
        "GPU 使用率": "GPU 使用率",
        "GitHub 返回了无法识别的响应。": "GitHub からの予期しない応答。",
        "Homebrew 返回了无法识别的响应。": "Homebrew からの予期しない応答。",
        "IDE 与编辑器缓存": "IDE とエディターのキャッシュ",
        "Internet 插件": "インターネットプラグイン",
        "PDF": "PDF",
        "Safari 扩展": "Safari 拡張機能",
        "Safari 扩展不能在本应用内开启、关闭或删除，以免破坏宿主应用的签名。请在 Safari 设置中管理它们。": "ホストアプリの署名が壊れるため、ここでは Safari 拡張機能のオン/オフや削除はできません。Safari の設定で管理してください。",
        "Spotlight 的整个搜索索引会被清除并重建。数小时内 Spotlight 搜索可能返回空结果（主目录越大耗时越久），系统搜索和智能文件夹也会受影响。": "Spotlight の検索インデックス全体が消去され、再構築されます。数時間（ホームフォルダが大きい場合はさらに長く）Spotlight 検索で結果が表示されないことがあり、システム検索とスマートフォルダも影響を受けます。",
        "URL Scheme": "URL スキーム",
        "Xcode 垃圾": "Xcode の不要ファイル",
        "iOS 设备备份": "iOS デバイスのバックアップ",
        "iPhone 和 iPad 的本地备份。": "iPhone と iPad のローカルバックアップ。",
        "macOS 的“哪类文件由哪个应用打开”数据库会被清除并重建。完成前（通常数小时），双击文件可能失败或打开错误应用，默认应用设置可能重置，Spotlight 启动应用也可能不可用。重启可加快恢复。": "ファイルの種類とそれを開くアプリを対応付ける macOS のデータベースが消去され、再構築されます。完了するまで（多くの場合は数時間）、ファイルをダブルクリックしても開けなかったり、別のアプリで開いたり、デフォルトのアプリ設定がリセットされたり、Spotlight からアプリを起動できなかったりすることがあります。再起動すると早く完了します。",
        "macOS 诊断日志。": "macOS の診断ログ。",
        "npm、Cargo、pip、Homebrew、Gradle 的可重建缓存。": "npm、Cargo、pip、Homebrew、Gradle の再生成可能なキャッシュ。",
        "~/Library/Logs/MacClean/operations.log — 30 天后自动清理": "~/Library/Logs/MacClean/operations.log：30日後に自動削除",
        "“邮件”应用的搜索索引会从头重建。重建完成前，邮件搜索和未读数可能不准确（大型邮箱通常需 10–30 分钟）。": "メールの検索インデックスが最初から再構築されます。完了するまで（大きなメールボックスでは通常10～30分）、メールの検索結果や未読数が正しく表示されないことがあります。",
        "一切就绪！": "準備ができました！",
        "一键清理": "ワンクリックでクリーンアップ",
        "上一级": "1つ上の階層へ",
        "下一步": "次へ",
        "下载": "ダウンロード",
        "不可写": "書き込み不可",
        "不能排除整个 /Volumes。": "/Volumes 全体は除外できません。",
        "不能排除整个主目录。": "ホームフォルダ全体を除外することはできません。",
        "主题": "テーマ",
        "仅显示错误": "エラーのみ",
        "仅移除 macOS 已标记可清理的 Time Machine 本地快照；不会删除你主动需要的内容。": "macOS がすでに削除対象としてマークした Time Machine ローカルスナップショットのみを削除します。必要なものは何も削除されません。",
        "仍要运行": "このまま実行",
        "从大到小": "サイズの大きい順",
        "从小到大": "サイズの小さい順",
        "代码": "コード",
        "代码编辑器的缓存（Cursor、Antigravity 等）。": "Cursor や Antigravity などのコードエディターのキャッシュ。",
        "以开源方式让你的 Mac 保持干净、快速和安全。": "Mac をクリーンかつ高速で安全に保つ、オープンソースの方法。",
        "优化": "最適化",
        "优化你的 Mac": "Mac を最適化",
        "会产生几分钟磁盘活动。该操作为只读，无论结果如何都不会更改磁盘内容。": "数分間ディスクにアクセスします。読み取り専用のため、結果にかかわらずディスク上の内容は一切変更されません。",
        "会删除本地 Time Machine 快照以释放空间。远程或备份盘上的快照不受影响，你仍可从 Time Machine 备份恢复。": "ディスク領域を解放するため、Time Machine ローカルスナップショットを削除します。リモートやバックアップ用ドライブ上のスナップショットには影響せず、Time Machine バックアップからの復元も引き続き可能です。",
