        "运行 docker system prune，删除未使用的镜像、已停止的容器、未使用的网络和构建缓存。此操作不可撤销（不会进入废纸篓）。正在运行的容器、使用中的镜像和命名卷不受影响，磁盘映像 Docker.raw 也不会被直接删除。": "docker system prune を実行し、未使用のイメージ、停止中のコンテナ、未使用のネットワーク、ビルドキャッシュを削除します。ゴミ箱に移動しないため元に戻せません。実行中のコンテナ、使用中のイメージ、名前付きボリュームは変更せず、Docker.raw を直接削除することもありません。",
