        "麦克风": "マイク",
        "会自动重建": "自動的に再作成",
        "可安全移除": "安全に削除可能",
        "清理前请检查": "クリーンアップ前に確認",
        "应用临时文件。每个应用下次启动时会自动重新生成。": "アプリの一時ファイル。次回各アプリを起動するときに自動的に再作成されます。",
        "由 macOS 自行管理的缓存，需要时会自动重建。": "macOS が管理するキャッシュです。必要に応じて自動的に再作成されます。",
        "下载和构建缓存。npm、Cargo、pip、Homebrew 和 Gradle 会在下次安装或构建时重新下载所需内容。": "ダウンロードとビルドのキャッシュです。npm、Cargo、pip、Homebrew、Gradle は次回のインストールやビルド時に必要なものを再ダウンロードします。",
        "仅编辑器缓存。Cursor 和 Antigravity 下次启动时会重新生成；你的设置和扩展不受影响。": "エディターのキャッシュのみです。Cursor と Antigravity は次回の起動時に再作成します。設定と拡張機能は変更されません。",
        "仅临时和缓存文件夹。Claude 和 Codex 会按需重新生成；绝不包含历史、记忆和会话。": "一時フォルダとキャッシュのみです。Claude と Codex が必要に応じて再作成します。履歴、メモリ、セッションは含まれません。",
        "应用为排查问题写下的诊断记录。应用不会回读旧日志，运行时会写新的日志。": "アプリがトラブルシューティングのために作成した診断テキスト。アプリは古いログを読み戻さず、実行時に新しいログを開始します。",
        "macOS 诊断日志。仅在排查过去的问题时有用；macOS 会继续写入新日志。": "macOS の診断ログ。過去の問題を調べる場合にのみ役立ちます。macOS は新しいログを書き込み続けます。",
        "无法读取的设置文件，或其应用已不再安装。这台 Mac 上没有任何东西在使用它们。": "読み取れない設定ファイル、またはアプリがすでにインストールされていない設定ファイルです。この Mac でこれらを使用しているものはありません。",
        "指向已不存在应用的登录项，因此无法启动任何东西。": "存在しないアプリを指しているため、何も起動できないログイン項目です。",
        "失败或被放弃的下载留下的文件。如仍需要，请重新下载。": "失敗または中断したダウンロードの残りファイルです。まだ必要な場合はファイルを再ダウンロードしてください。",
        "未完成下载的部分文件和超过一天的临时文件。下载仍在进行时请勿清理。": "未完了のダウンロードの部分ファイルと、1日以上前の一時ファイル。ダウンロード中はクリーンアップしないでください。",
        "应用在一周多以前下载的安装包。安装程序运行后就不再需要，需要时可重新下载。": "アプリが1週間以上前にダウンロードしたインストールパッケージです。実行後は不要になり、必要なら再ダウンロードできます。",
        "以已不再安装的应用命名的支持文件夹（每行的名称就是该应用的 ID）。以后重新安装该应用会从头开始。": "インストールされていないアプリのサポートフォルダです。各行の名前はアプリの ID です。アプリを再インストールすると初期状態で起動します。",
        "你不使用的语言翻译。移除会修改应用包；如需恢复请重新安装应用。": "使用しない言語の翻訳。削除するとアプリバンドルが変更されます。元に戻すにはアプリを再インストールしてください。",
        "文档的旧自动保存版本。当前版本会保留，但清理后无法再浏览旧版本。": "自動保存された書類の古いバージョン。現在のバージョンは残りますが、クリーンアップ後は古いバージョンを表示できなくなります。",
        "超过 30 天的 iPhone 和 iPad 本地备份。如果这是设备唯一的备份，请保留或先备份到 iCloud。": "30日以上前の iPhone と iPad のローカルバックアップ。デバイスの唯一のバックアップの場合は保持するか、先に iCloud にバックアップしてください。",
        "从应用中移除这台 Mac 无法运行的 CPU 代码。会直接修改应用；只有重新安装才能撤销。": "この Mac で実行できない CPU 用コードをアプリから削除します。アプリを直接変更するため、元に戻すには再インストールが必要です。",
        "DerivedData 和 Previews 会在下次构建时重建，Device Support 会在连接设备时重新复制。Archives 和模拟器数据无法重新生成；如需旧构建或崩溃符号请保留。": "DerivedData と Previews は次回のビルドで、Device Support はデバイスの接続時に再作成されます。アーカイブとシミュレータのデータは再生成できません。古いビルドやクラッシュ解析用シンボルが必要な場合は保持してください。",
        "已不在这台 Mac 上的账户的整个个人文件夹。请逐个核对名称：暂时离线的网络账户看起来完全一样。": "この Mac に存在しなくなったアカウントのホームフォルダ全体です。一時的にオフラインのネットワークアカウントも同じように表示されるため、名前を必ず確認してください。",
        "下载文件夹中超过一周的磁盘映像，通常是已运行过的安装程序。如需要可重新下载。": "ダウンロードフォルダ内にある1週間以上前のディスクイメージで、通常はすでに実行済みのインストーラです。必要なら再ダウンロードできます。",
        "邮件保存在磁盘上的附件副本。IMAP 和 Exchange 账户可从服务器重新下载，POP 账户不行。": "メールがディスクに保存した添付ファイルのコピーです。IMAP と Exchange のアカウントでは再ダウンロードできますが、POP ではできません。",
        "已在废纸篓中。清倒是永久性的，无法撤销。": "すでにゴミ箱に入っています。ゴミ箱を空にすると完全に削除され、元に戻せません。",
        "匹配已知恶意软件特征。如果它属于你有意安装的软件，请先检查路径。": "既知のマルウェアのシグネチャと一致しました。意図的にインストールしたソフトウェアに属しているかどうか、まずパスを確認してください。",
        "你的浏览历史和跟踪数据。清理后无法恢复；Cookie 和登录会话会保留。": "閲覧履歴と追跡データ。クリーンアップ後は復元できません。Cookie とログインセッションは残ります。",
        "最近项目列表和类似痕迹。应用的“最近打开”菜单将会清空。": "最近使った項目の一覧などの履歴です。アプリの「最近使った項目を開く」メニューが空になります。",
        "你自己的文件，仅按大小挑选。这里没有任何东西天生就是垃圾；请逐个检查。": "サイズだけで抽出したユーザー自身のファイルです。不要なファイルとは限らないため、1つずつ確認してください。",
        "很久没打开过的你自己的文件。旧并不代表不需要；请逐个检查。": "長い間開いていないユーザー自身のファイルです。古いからといって不要とは限らないため、1つずつ確認してください。",
        "逐字节完全相同的副本。每个需要的文件请至少保留一份。": "バイト単位で同一のコピー。必要なファイルは、それぞれ少なくとも1つのコピーを残してください。",
        "可能的威胁": "可能性のある脅威",
        "Apple XProtect 特征：{name}": "Apple XProtect のシグネチャ：{name}",
        "在 Apple 的 Safari 扩展黑名单中：{name}": "Apple の Safari 拡張機能ブロックリストに掲載：{name}",
        "名称与已知家族相符：{name}": "名前が既知のファミリーと一致：{name}",
        "启动代理会运行“{name}”": "起動エージェントが「{name}」を実行します",
        "标记原因": "検出された理由",
        "没有可直接移除的威胁": "Mac Sai が削除できる脅威はありません",
        "已发现，但需要管理员才能移除": "検出されましたが、削除には管理者権限が必要です",
        "这些项目位于 Mac Sai 无法修改的系统文件夹中。请在 Finder 中显示每一项，然后输入管理员密码将其移到废纸篓。": "これらは Mac Sai が変更できないシステムフォルダにあります。それぞれを Finder に表示し、管理者パスワードを使ってそこからゴミ箱に移動してください。",
        "Apple XProtect {version}：{count} 个哈希值，{blocked} 个被屏蔽的 Safari 扩展": "Apple XProtect {version}：ハッシュ {count} 件、ブロックされた Safari 拡張機能 {blocked} 件",
        "未在这台 Mac 上找到 Apple XProtect 数据": "この Mac で Apple XProtect のデータが見つかりません",
        "在黑名单上或由社区报告、但也可能是你有意安装的软件的项目。": "ブロックリストに一致するか、コミュニティから報告された項目ですが、意図的にインストールしたソフトウェアである可能性もあります。",
        "不会预先勾选。黑名单可能也涵盖曾经正当的软件的旧版本，社区报告也未经厂商确认，删除前请逐个核对。": "事前に選択される項目はありません。ブロックリストにはかつて正当だったソフトウェアの古いバージョンが含まれることがあり、コミュニティからの報告も開発元によって確認されたものではありません。削除する前に各項目を確認してください。",
        "正在比对 XProtect 和 MalwareBazaar 哈希值...": "XProtect と MalwareBazaar のハッシュを照合しています...",
        "已报告至 MalwareBazaar：{name}": "MalwareBazaar に報告済み：{name}",
        "MalwareBazaar：未启用（可在设置中添加免费的 Auth-Key）": "MalwareBazaar：オフ（設定で無料の Auth-Key を追加できます）",
        "MalwareBazaar：{count} 个哈希值，更新于 {date}": "MalwareBazaar：ハッシュ {count} 件、{date} に更新",
        "恶意软件数据库": "マルウェアデータベース",
        "版本 {version}：{hashes} 个哈希值，{blocked} 个被屏蔽的 Safari 扩展。由 macOS 自动更新。": "バージョン {version}：ハッシュ {hashes} 件、ブロックされた Safari 拡張機能 {blocked} 件。macOS によって自動的に最新の状態に保たれます。",
        "可选。按下“立即更新”时，使用你免费的 abuse.ch Auth-Key 下载最近报告的 macOS 恶意软件样本哈希值。每次请求只发送你的 Auth-Key 和查询内容，绝不发送文件哈希值或路径。如果某个哈希与已签名的文件匹配，macOS 会向 Apple 查询其签名证书是否已被吊销。匹配项不会预先勾选。": "オプション。「今すぐアップデート」を押すと、無料の abuse.ch Auth-Key を使って、最近報告された macOS マルウェアサンプルのハッシュをダウンロードします。各リクエストで送信されるのは Auth-Key とクエリのみで、ファイルのハッシュやパスは一切送信されません。ハッシュが署名済みのファイルと一致した場合、macOS はその署名証明書が失効しているかどうかを Apple に問い合わせます。一致した項目が事前に選択されることはありません。",
        "abuse.ch Auth-Key": "abuse.ch の Auth-Key",
        "保存密钥": "キーを保存",
        "移除密钥和哈希值": "キーとハッシュを削除",
        "立即更新": "今すぐアップデート",
        "获取免费密钥": "無料のキーを取得",
        "正在更新…": "アップデート中…",
        "密钥已保存在你的钥匙串中。": "キーをキーチェーンに保存しました。",
        "无法将密钥保存到钥匙串。": "キーをキーチェーンに保存できませんでした。",
        "无法移除密钥或哈希值。": "キーまたはハッシュを削除できませんでした。",
        "Auth-Key 被拒绝。请在 auth.abuse.ch 检查。": "Auth-Key が拒否されました。auth.abuse.ch で確認してください。",
        "尚未下载哈希值。": "ハッシュはまだダウンロードされていません。",
        "已更新：新增 {added} 个，共 {total} 个哈希值。": "アップデート完了：新規 {added} 件、合計 {total} 件のハッシュ。",
        "部分查询失败：{list}": "一部のクエリが失敗しました：{list}",
        "更新失败：{list}": "アップデートに失敗しました：{list}",
        "无法保存下载的哈希列表。": "ダウンロードしたハッシュリストを保存できませんでした。",
        "服务器要求重定向，已拒绝": "サーバーがリダイレクトを要求したため拒否しました",
        "响应过大": "応答が大きすぎます",
        "响应格式不正确": "応答の形式が正しくありません",
        "正在扫描磁盘…": "ディスクをスキャン中…",
        "没有找到项目": "項目が見つかりませんでした",
        "系统": "システム",
