        "把最近一次清理整批恢复到原位置。已清空废纸篓或原路径已有文件的项会被跳过。": "Son temizlemenin tamamını tek tıklamayla geri alın. Çöp Sepetinden zaten boşaltılmış olan veya özgün konumunda artık başka bir dosya bulunan öğeler atlanır.",
        "旧版运行时": "Eski çalışma zamanı",
        "12 个月": "12 ay",
        "删除所选模拟器项目…": "Seçilen Simülatör Öğelerini Sil…",
        "未能完成": "Tamamlanamadı",
        "这台 Mac 上没有找到 Docker 或 Xcode 模拟器。": "Bu Mac'te Docker veya Xcode simülatörü bulunamadı.",
        "Safari 扩展随 App 一起安装，由 macOS 管理，因此此列表只读。将改为打开“设置”。": "Safari uzantıları uygulamalarla birlikte yüklenir ve macOS tarafından yönetilir; bu nedenle bu liste salt okunurdur. Bunun yerine Ayarlar açılacak.",
        "超时，已停止": "Zaman aşımı, durduruldu",
        "关于此扩展": "Bu uzantı hakkında",
        "清理会永久删除所有已停止的容器及其中的数据。正在运行的容器不受影响。": "Temizleme, durdurulmuş tüm kapsayıcıları ve içlerindeki verileri kalıcı olarak siler. Çalışan kapsayıcılar etkilenmez.",
        "Docker 和 Xcode 模拟器占用的空间。只显示在这台 Mac 上找到的工具，且不会自动勾选任何项目。": "Docker ve Xcode simülatörlerinin kapladığı alan. Yalnızca bu Mac'te bulunan araçlar gösterilir ve hiçbir şey otomatik olarak seçilmez.",
        "容器": "Kapsayıcılar",
        "使用渐进式 SHA-256 哈希检测\n查找重复文件": "Aşamalı SHA-256 karmasıyla\nyinelenen dosyaları bulun",
        "请选择你的项目文件夹，而不是系统文件夹或资源库。": "Sistem klasörü veya Kitaplık yerine proje klasörünüzü seçin.",
        "Chrome、Brave、Edge、Arc、Firefox 和 Safari 的扩展。名称与已知广告软件家族相符的会标为可疑。": "Chrome, Brave, Edge, Arc, Firefox ve Safari uzantıları. Adı bilinen reklam yazılımı aileleriyle eşleşenler Şüpheli olarak işaretlenir.",
        "项目中已安装的依赖和构建产物。运行项目的安装或构建命令即可找回；之后第一次构建会更慢。": "Projelere yüklenmiş bağımlılıklar ve derleme çıktıları. Projenin yükleme veya derleme komutunu çalıştırarak geri getirebilirsiniz; sonraki ilk derleme daha uzun sürer.",
        "无法读取 Safari 扩展列表。请在 Safari 设置 > 扩展中查看。": "Safari uzantılarının listesi okunamadı. Safari Ayarları > Uzantılar bölümünden kontrol edin.",
        "可疑": "Şüpheli",
        "此操作不可撤销，不会进入废纸篓。": "Bu işlem geri alınamaz; hiçbir şey Çöp Sepetine gitmez.",
        "这只会忘掉恢复记录，废纸篓里的文件不会被动。之后就不能一键恢复这些清理了。": "Bu yalnızca geri yükleme listesini unutur. Çöp Sepetindeki hiçbir şeye dokunulmaz, ancak bu temizlemeler artık tek tıklamayla geri yüklenemez.",
        "不会自动勾选。": "Hiçbir şey otomatik olarak seçilmez.",
        "正在查找未使用的应用…": "Kullanılmayan uygulamalar aranıyor…",
        "6 个月": "6 ay",
        "Spotlight 没有应用的使用记录": "Spotlight'ta uygulamalarınız için kullanım geçmişi yok",
        "浏览器扩展": "Tarayıcı Uzantıları",
        "支持文件": "Destek dosyaları",
        "选择项目文件夹（例如 ~/Code），查找 node_modules、venv、target、build 等可重建目录。": "node_modules, venv, target ve build gibi yeniden oluşturulabilir klasörleri bulmak için bir proje klasörü seçin (örneğin ~/Code).",
        "恢复": "Geri yükle",
        "正在查找项目…": "Projeler aranıyor…",
        "卷": "Birimler",
        "3 个月": "3 ay",
        "清理只会删除悬空（无标签）镜像，带标签的镜像会保留。": "Temizleme yalnızca sahipsiz (etiketsiz) imajları kaldırır; etiketli imajlar korunur.",
        "Firefox 正在运行，因此未删除任何内容。请在 Firefox 中通过“工具 > 附加组件和主题”移除此扩展。": "Firefox açık olduğundan hiçbir şey silinmedi. Uzantıyı Firefox'ta Araçlar > Eklentiler ve Temalar bölümünden kaldırın.",
        "删除运行时会先关闭正在使用它的模拟器，这些模拟器之后将不可用。": "Bir çalışma zamanını silmek önce onu kullanan simülatörleri kapatır; bu simülatörler daha sonra kullanılamaz.",
        "在 Chrome、Brave、Edge、Arc、Firefox 或 Safari 中未找到扩展": "Chrome, Brave, Edge, Arc, Firefox veya Safari'de uzantı bulunamadı",
        "没有符合条件的应用": "Bu dönemde kullanılmayan uygulama yok",
        "已从废纸篓清空：%ld": "Çöp Sepetinden zaten boşaltılmış: %ld",
        "此扩展由管理策略安装，删除文件夹后 {browser} 会重新安装它。如果你不认识它，请在系统设置中搜索“描述文件”或“设备管理”，并移除你不认识的描述文件。": "Bu uzantı bir yönetim ilkesiyle yüklendiğinden klasör silinse bile {browser} uygulaması onu yeniden yükler. Tanımıyorsanız Sistem Ayarları'nda Profiller veya Aygıt Yönetimi'ni arayın ve tanımadığınız profilleri kaldırın.",
        "卸载…": "Kaldır…",
        "已将扩展移到废纸篓。": "Uzantı Çöp Sepetine taşındı.",
        "永久清理所选 Docker 项目？": "Seçili Docker öğeleri kalıcı olarak silinsin mi?",
        "已恢复：%ld": "Geri yüklendi: %ld",
        "构建缓存": "Derleme Önbelleği",
        "Xcode 模拟器": "Xcode Simülatörleri",
        "%ld 项": "%ld öğe",
        "清除历史": "Geçmişi Temizle",
        "清除清理历史？": "Temizleme geçmişi silinsin mi?",
        "上次打开": "Son açılış",
        "未找到项目垃圾": "Gereksiz proje dosyası bulunamadı",
        "Chrome 正在运行，因此未删除任何内容。请在 Chrome 中通过“窗口 > 扩展程序”移除此扩展。": "Chrome açık olduğundan hiçbir şey silinmedi. Uzantıyı Chrome'da Pencere > Uzantılar bölümünden kaldırın.",
        "项目垃圾": "Gereksiz Proje Dosyaları",
        "内置": "Yerleşik",
        "重复文件检测会使用 SHA-256 哈希每个候选文件。\n大型个人目录可能需要 5–15 分钟。": "Yinelenen dosya algılama, her aday dosyanın SHA-256 karmasını hesaplar.\nBüyük ana klasörlerde bu işlem 5-15 dakika sürebilir.",
        "清理历史": "Temizleme Geçmişi",
        "删除完成": "Silindi",
        "正在计算文件夹大小…": "Klasör boyutları hesaplanıyor…",
        "还没有可恢复的清理记录": "Henüz geri alınabilecek temizleme yok",
        "已找到 Docker，但它没有响应。请先启动 Docker Desktop，然后点“刷新”。": "Docker bulundu ancak yanıt vermiyor. Önce Docker Desktop'ı başlatın, ardından Yenile'ye tıklayın.",
        "永久删除所选模拟器项目？": "Seçilen simülatör öğeleri kalıcı olarak silinsin mi?",
        "移除扩展？": "Uzantı kaldırılsın mı?",
        "永久清理": "Kalıcı olarak temizle",
        "按上次打开时间列出应用，并按占用空间排序。一键转到卸载器。": "Uygulamaları son açılma zamanına göre listeler ve kapladıkları alana göre sıralar. Tek tıklamayla Kaldırıcı'ya gönderin.",
        "正在读取扩展…": "Uzantılar okunuyor…",
        "原位置已有文件，已跳过：%ld": "Özgün konumda dosya olduğu için atlanan: %ld",
        "扫描 Mac 中的垃圾文件、恶意威胁\n和性能问题": "Mac'inizi gereksiz dosyalar, kötü amaçlı tehditler\nve performans sorunları için tarayın",
        "此扩展内置于 {browser}，无法移除。": "Bu uzantı {browser} uygulamasında yerleşiktir ve kaldırılamaz.",
        "未使用的应用": "Kullanılmayan Uygulamalar",
        "名称与已知广告软件家族相符。这只是提示，并非确认。": "Ad, bilinen bir reklam yazılımı ailesiyle eşleşiyor. Bu yalnızca bir ipucudur, kesin bir tespit değildir.",
        "未找到 Docker": "Docker bulunamadı",
        "卷可能保存着数据库等数据，Mac Sai 不会清理它们。如需删除，请使用 Docker Desktop 或 Docker 命令行。": "Birimler veri tabanı gibi veriler içerebilir; Mac Sai bunları temizlemez. Kaldırmak için Docker Desktop'ı veya Docker komut satırını kullanın.",
        "不可用的模拟器": "Kullanılamayan simülatör",
        "后台": "Arka plan",
        "这次清理，你没花一分钱。": "Bu temizleme size hiçbir şeye mal olmadı.",
        "没有订阅，没有广告，没有追踪。Mac Sai 是我和几位志愿者在业余时间做的。如果它帮你省下了买清理软件的钱，请我喝杯咖啡，让它对所有人继续免费。": "Abonelik yok, reklam yok, takip yok. Mac Sai'yi birkaç gönüllüyle birlikte boş zamanlarımızda geliştiriyoruz. Ücretli bir temizleme uygulamasına para vermenizi önlediyse bir kahve ısmarlayarak herkes için ücretsiz kalmasına yardımcı olabilirsiniz.",
        "请我喝杯咖啡": "Bana bir kahve ısmarla",
        "以后再说": "Belki sonra",
        "不再提示": "Bir daha sorma",
        "谢谢你。正因为有你，它才能一直免费。": "Teşekkürler. Ücretsiz kalmasını sizin gibi destekçiler sağlıyor.",
        "支持 Mac Sai": "Mac Sai'yi destekleyin",
        "支持者": "Destekçiler",
        "感谢你们让 Mac Sai 保持免费：{names}。": "Mac Sai'yi ücretsiz tuttuğunuz için teşekkürler: {names}.",
        "支持 Mac Sai 的会员会列在这里。来做第一个吧。": "Mac Sai'yi ücretsiz tutan üyeler burada listelenir. İlk siz olun.",
        "成为会员，或请开发者喝杯咖啡": "Üye olun veya geliştiriciye bir kahve ısmarlayın",
        "1 - 3 个月": "1 - 3 ay",
        "3 - 6 个月": "3 - 6 ay",
        "30 天内不再显示": "30 gün boyunca gizle",
        "6 个月 - 1 年": "6 ay - 1 yıl",
        "AI 工具缓存": "AI Araç Önbellekleri",
        "AI 编码工具的缓存（Claude、Codex）；不含历史与会话。": "AI kodlama araçlarından (Claude, Codex) önbellekler. Geçmiş ve oturumlar hariçtir.",
        "CPU": "CPU",
        "GPU 使用率": "GPU kullanımı",
        "GitHub 返回了无法识别的响应。": "GitHub tanınmayan bir yanıt döndürdü.",
        "Homebrew 返回了无法识别的响应。": "Homebrew tanınmayan bir yanıt döndürdü.",
        "IDE 与编辑器缓存": "IDE ve Düzenleyici Önbellekleri",
        "Internet 插件": "İnternet Eklentileri",
        "PDF": "PDF'ler",
        "Safari 扩展": "Safari Uzantıları",
        "Safari 扩展不能在本应用内开启、关闭或删除，以免破坏宿主应用的签名。请在 Safari 设置中管理它们。": "Safari uzantıları, ana uygulamanın imzasını bozmamak için burada açılamaz, kapatılamaz veya silinemez. Bunları Safari Ayarları'nda yönetin.",
        "Spotlight 的整个搜索索引会被清除并重建。数小时内 Spotlight 搜索可能返回空结果（主目录越大耗时越久），系统搜索和智能文件夹也会受影响。": "Spotlight'ın tüm arama dizini silinir ve yeniden oluşturulur. Spotlight araması birkaç saat boyunca boş sonuç verebilir (ana klasör ne kadar büyükse o kadar uzun sürer); sistem araması ve Akıllı Klasörler de etkilenir.",
        "URL Scheme": "URL Şeması",
        "Xcode 垃圾": "Gereksiz Xcode Dosyaları",
        "iOS 设备备份": "iOS Aygıt Yedekleri",
        "iPhone 和 iPad 的本地备份。": "iPhone ve iPad aygıtlarının yerel yedekleri.",
        "macOS 的“哪类文件由哪个应用打开”数据库会被清除并重建。完成前（通常数小时），双击文件可能失败或打开错误应用，默认应用设置可能重置，Spotlight 启动应用也可能不可用。重启可加快恢复。": "macOS'un hangi dosya türünün hangi uygulamayla açılacağını belirleyen veri tabanı silinir ve yeniden oluşturulur. İşlem tamamlanana kadar (genellikle birkaç saat) dosyalara çift tıklamak başarısız olabilir veya yanlış uygulamayı açabilir, varsayılan uygulama ayarları sıfırlanabilir ve uygulamaları Spotlight ile başlatmak çalışmayabilir. Yeniden başlatmak bu süreyi kısaltır.",
        "macOS 诊断日志。": "macOS tanılama günlükleri.",
        "npm、Cargo、pip、Homebrew、Gradle 的可重建缓存。": "npm, Cargo, pip, Homebrew ve Gradle'ın yeniden oluşturulabilir önbellekleri.",
        "~/Library/Logs/MacClean/operations.log — 30 天后自动清理": "~/Library/Logs/MacClean/operations.log: 30 gün sonra otomatik olarak temizlenir",
        "“邮件”应用的搜索索引会从头重建。重建完成前，邮件搜索和未读数可能不准确（大型邮箱通常需 10–30 分钟）。": "Mail'in arama dizini sıfırdan yeniden oluşturulur. İşlem tamamlanana kadar (büyük posta kutularında genellikle 10-30 dakika) Mail araması ve okunmamış sayıları yanlış olabilir.",
        "一切就绪！": "Her şey hazır!",
