        "优化": "Optimizasyon",
        "优化你的 Mac": "Mac'inizi optimize edin",
        "会产生几分钟磁盘活动。该操作为只读，无论结果如何都不会更改磁盘内容。": "Birkaç dakikalık disk etkinliği oluşturur. Salt okunurdur: sonuç ne olursa olsun diskte hiçbir şey değişmez.",
        "会删除本地 Time Machine 快照以释放空间。远程或备份盘上的快照不受影响，你仍可从 Time Machine 备份恢复。": "Disk alanı boşaltmak için yerel Time Machine anlık görüntüleri silinir. Uzak veya yedekleme diskindeki anlık görüntüler etkilenmez; Time Machine yedeğinizden geri yükleme yapmaya devam edebilirsiniz.",
