        "Base 资源、Mac Sai 的界面语言以及你的 Mac 在“语言与地区”中设置的语言会始终保留。已勾选的语言会保留；未勾选的语言文件可由“系统垃圾”移除。": "Base kaynakları, Mac Sai'nin arayüz dilleri ve Mac'inizin Dil ve Bölge ayarlarındaki diller her zaman korunur. İşaretli diller korunur; işaretlenmemiş dil dosyaları Gereksiz Sistem Dosyaları tarafından kaldırılabilir.",
