        "输入的二进制文件不是通用 Mach-O": "girdi ikili dosyası evrensel Mach-O değil",
        "运行 docker system prune，删除未使用的镜像、已停止的容器、未使用的网络和构建缓存。此操作不可撤销（不会进入废纸篓）。正在运行的容器、使用中的镜像和命名卷不受影响，磁盘映像 Docker.raw 也不会被直接删除。": "docker system prune komutuyla kullanılmayan imajları, durdurulmuş kapsayıcıları, kullanılmayan ağları ve derleme önbelleğini kaldırır. Bu işlem geri alınamaz; öğeler Çöp Sepetine gitmez. Çalışan kapsayıcılar, kullanılan imajlar ve adlandırılmış birimler korunur. Docker.raw disk görüntüsü doğrudan silinmez.",
        "运行中": "Çalışıyor",
