        "选中的项目会移到废纸篓，如有需要仍可恢复。": "Seçilen öğeler Çöp Sepetine taşınır; gerekirse geri yükleyebilirsiniz.",
        "选择一个应用以查看相关文件": "Dosyalarını görmek için bir uygulama seçin",
        "选择应用图标旁显示的紧凑数值。GPU 或电池温度不可用时显示 --。": "Uygulama simgesinin yanında gösterilecek kısa değeri seçin. GPU veya pil sıcaklığı kullanılamadığında -- gösterilir.",
        "选择文件": "Dosyaları Seçin",
        "选择要从清理中排除的文件夹。": "Temizlemenin dışında tutulacak bir klasör seçin.",
        "通常没有可见影响——这些脚本与 macOS 夜间自动运行的维护脚本相同。": "Genellikle görünür bir etkisi olmaz; bunlar macOS'un her gece kendiliğinden çalıştırdığı bakım betikleriyle aynıdır.",
        "通用": "Genel",
