        "重建 Spotlight 搜索索引，提高搜索准确性": "Arama doğruluğunu artırmak için Spotlight arama dizinini yeniden oluşturun",
        "重建 Spotlight 索引": "Spotlight dizinini yeniden oluştur",
        "重建“邮件”数据库索引，以修复搜索和性能问题": "Arama ve performans sorunlarını gidermek için Mail veri tabanını yeniden dizinleyin",
