        "重新读取权限列表": "İzin listesini yenile",
        "重试": "Yeniden dene",
        "错误": "Hata",
        "长时间未打开的文件。": "Uzun zamandır açmadığınız dosyalar.",
        "防护": "Koruma",
        "隐私清理": "Gizlilik",
        "需要在“系统设置 → 登录项”中批准": "Sistem Ayarları → Oturum Açma Öğeleri bölümünde onay gerekiyor",
        "需要在“系统设置 → 通用 → 登录项”中批准": "Sistem Ayarları → Genel → Oturum Açma Öğeleri bölümünde onay gerekiyor",
        "需要完全磁盘访问权限": "Tam Disk Erişimi gerekiyor",
        "需要完全磁盘访问权限才能列出应用": "Uygulamaları listelemek için Tam Disk Erişimi gerekiyor",
        "非 APFS 卷": "APFS olmayan birim",
        "非普通文件": "normal bir dosya değil",
        "音频": "Ses",
        "验证启动磁盘": "Başlangıç diskini doğrula",
        "高级": "GELİŞMİŞ",
        "麦克风": "Mikrofon",
        "会自动重建": "Otomatik olarak yeniden oluşturulur",
        "可安全移除": "Kaldırmak güvenli",
        "清理前请检查": "Temizlemeden önce gözden geçirin",
        "应用临时文件。每个应用下次启动时会自动重新生成。": "Uygulama geçici dosyaları. Her uygulamanın bir sonraki başlatılışında otomatik olarak yeniden oluşturulur.",
        "由 macOS 自行管理的缓存，需要时会自动重建。": "macOS'un yönettiği önbellekler. Gerektiğinde otomatik olarak yeniden oluşturulurlar.",
        "下载和构建缓存。npm、Cargo、pip、Homebrew 和 Gradle 会在下次安装或构建时重新下载所需内容。": "İndirme ve derleme önbellekleri. npm, Cargo, pip, Homebrew ve Gradle sonraki yükleme veya derlemede gerekenleri yeniden indirir.",
        "仅编辑器缓存。Cursor 和 Antigravity 下次启动时会重新生成；你的设置和扩展不受影响。": "Yalnızca düzenleyici önbellekleri. Cursor ve Antigravity bir sonraki açılışta bunları yeniden oluşturur; ayarlarınıza ve uzantılarınıza dokunulmaz.",
        "仅临时和缓存文件夹。Claude 和 Codex 会按需重新生成；绝不包含历史、记忆和会话。": "Yalnızca geçici klasörler ve önbellekler. Claude ve Codex bunları gerektiğinde yeniden oluşturur; geçmiş, bellek ve oturumlar asla dahil edilmez.",
        "应用为排查问题写下的诊断记录。应用不会回读旧日志，运行时会写新的日志。": "Uygulamaların sorun giderme için yazdığı tanılama kayıtları. Uygulamalar eski günlükleri geri okumaz, çalışırken yenilerini yazar.",
        "macOS 诊断日志。仅在排查过去的问题时有用；macOS 会继续写入新日志。": "macOS tanılama günlükleri. Yalnızca geçmiş bir sorunu araştırırken işe yarar; macOS yeni günlükler yazmaya devam eder.",
        "无法读取的设置文件，或其应用已不再安装。这台 Mac 上没有任何东西在使用它们。": "Okunamayan veya uygulaması artık yüklü olmayan ayar dosyaları. Bu Mac'teki hiçbir şey bunları kullanmıyor.",
        "指向已不存在应用的登录项，因此无法启动任何东西。": "Artık var olmayan uygulamaları gösteren oturum açma öğeleri; bu nedenle hiçbir şeyi başlatamazlar.",
        "失败或被放弃的下载留下的文件。如仍需要，请重新下载。": "Başarısız olan veya yarıda bırakılan indirmelerden kalan dosyalar. Hâlâ gerekiyorsa yeniden indirin.",
        "未完成下载的部分文件和超过一天的临时文件。下载仍在进行时请勿清理。": "Tamamlanmamış indirmelere ait kısmi dosyalar ve bir günden eski geçici dosyalar. İndirme devam ederken temizlemeyin.",
        "应用在一周多以前下载的安装包。安装程序运行后就不再需要，需要时可重新下载。": "Uygulamaların bir haftadan uzun süre önce indirdiği yükleme paketleri. Yükleyici çalıştırıldıktan sonra gerekmez; gerekirse yeniden indirilebilir.",
        "以已不再安装的应用命名的支持文件夹（每行的名称就是该应用的 ID）。以后重新安装该应用会从头开始。": "Artık yüklü olmayan uygulamaların adını taşıyan destek klasörleri (her satırdaki ad uygulamanın kimliğidir). Uygulamayı daha sonra yeniden yüklerseniz sıfırdan başlar.",
        "你不使用的语言翻译。移除会修改应用包；如需恢复请重新安装应用。": "Kullanmadığınız dillerin çevirileri. Kaldırmak uygulama paketini değiştirir; geri almak için uygulamayı yeniden yükleyin.",
        "文档的旧自动保存版本。当前版本会保留，但清理后无法再浏览旧版本。": "Belgelerinizin otomatik kaydedilmiş eski sürümleri. Geçerli sürüm korunur, ancak temizledikten sonra eski sürümlere göz atamazsınız.",
        "超过 30 天的 iPhone 和 iPad 本地备份。如果这是设备唯一的备份，请保留或先备份到 iCloud。": "30 günden eski yerel iPhone ve iPad yedekleri. Aygıtın tek yedeği buysa saklayın veya önce iCloud'a yedekleyin.",
        "从应用中移除这台 Mac 无法运行的 CPU 代码。会直接修改应用；只有重新安装才能撤销。": "Uygulamalardan bu Mac'in çalıştıramadığı CPU kodunu kaldırır. Uygulamaları doğrudan değiştirir; değişiklik yalnızca yeniden yüklemeyle geri alınabilir.",
        "DerivedData 和 Previews 会在下次构建时重建，Device Support 会在连接设备时重新复制。Archives 和模拟器数据无法重新生成；如需旧构建或崩溃符号请保留。": "DerivedData ve Previews sonraki derlemede yeniden oluşturulur; Device Support bir aygıt bağlandığında yeniden kopyalanır. Arşivler ve simülatör verileri yeniden oluşturulamaz. Eski derlemelere veya çökme sembollerine ihtiyacınız varsa bunları saklayın.",
        "已不在这台 Mac 上的账户的整个个人文件夹。请逐个核对名称：暂时离线的网络账户看起来完全一样。": "Artık bu Mac'te bulunmayan hesapların ana klasörlerinin tamamı. Her adı tek tek kontrol edin: geçici olarak çevrimdışı olan bir ağ hesabı da tamamen aynı görünür.",
        "下载文件夹中超过一周的磁盘映像，通常是已运行过的安装程序。如需要可重新下载。": "İndirilenler klasöründeki bir haftadan eski disk görüntüleri; genellikle zaten çalıştırılmış yükleyicilerdir. Gerekirse yeniden indirebilirsiniz.",
        "邮件保存在磁盘上的附件副本。IMAP 和 Exchange 账户可从服务器重新下载，POP 账户不行。": "Mail'in diske kaydettiği eklerin kopyaları. IMAP ve Exchange hesaplarında sunucudan yeniden indirilebilirler, ancak POP hesaplarında indirilemezler.",
        "已在废纸篓中。清倒是永久性的，无法撤销。": "Zaten Çöp Sepetinde. Boşaltma kalıcıdır ve geri alınamaz.",
        "匹配已知恶意软件特征。如果它属于你有意安装的软件，请先检查路径。": "Bilinen bir kötü amaçlı yazılım imzasıyla eşleşiyor. Bilerek yüklediğiniz bir yazılıma ait olabilir; önce yolu kontrol edin.",
        "你的浏览历史和跟踪数据。清理后无法恢复；Cookie 和登录会话会保留。": "Tarama geçmişiniz ve izleme verileriniz. Temizlendikten sonra geri yüklenemez; çerezler ve oturumlar korunur.",
        "最近项目列表和类似痕迹。应用的“最近打开”菜单将会清空。": "Son öğe listeleri ve benzer izler. Uygulamaların Son Kullanılanlar menüleri boşaltılır.",
        "你自己的文件，仅按大小挑选。这里没有任何东西天生就是垃圾；请逐个检查。": "Yalnızca boyutuna göre seçilen kendi dosyalarınız. Buradaki hiçbir şey kendiliğinden gereksiz değildir; her birini kontrol edin.",
        "很久没打开过的你自己的文件。旧并不代表不需要；请逐个检查。": "Uzun zamandır açmadığınız kendi dosyalarınız. Eski olması gereksiz olduğu anlamına gelmez; her birini kontrol edin.",
        "逐字节完全相同的副本。每个需要的文件请至少保留一份。": "Bayt bayt özdeş kopyalar. İhtiyacınız olan her dosyanın en az bir kopyasını saklayın.",
        "可能的威胁": "Olası Tehditler",
        "Apple XProtect 特征：{name}": "Apple XProtect imzası: {name}",
        "在 Apple 的 Safari 扩展黑名单中：{name}": "Apple'ın Safari uzantısı engelleme listesinde: {name}",
        "名称与已知家族相符：{name}": "Ad, bilinen bir aileyle eşleşiyor: {name}",
        "启动代理会运行“{name}”": "Launch Agent, “{name}” öğesini çalıştırıyor",
        "标记原因": "Neden işaretlendi",
        "没有可直接移除的威胁": "Mac Sai'nin kaldırabileceği tehdit yok",
        "已发现，但需要管理员才能移除": "Bulundu, ancak kaldırmak için yönetici gerekiyor",
        "这些项目位于 Mac Sai 无法修改的系统文件夹中。请在 Finder 中显示每一项，然后输入管理员密码将其移到废纸篓。": "Bunlar Mac Sai'nin değiştiremeyeceği sistem klasörlerinde. Her birini Finder'da gösterin ve oradan yönetici parolanızla Çöp Sepetine taşıyın.",
        "Apple XProtect {version}：{count} 个哈希值，{blocked} 个被屏蔽的 Safari 扩展": "Apple XProtect {version}: {count} karma, {blocked} engellenmiş Safari uzantısı",
        "未在这台 Mac 上找到 Apple XProtect 数据": "Bu Mac'te Apple XProtect verisi bulunamadı",
        "在黑名单上或由社区报告、但也可能是你有意安装的软件的项目。": "Engelleme listesiyle eşleşen veya topluluk tarafından bildirilen, ancak bilerek yüklediğiniz yazılımlar da olabilecek öğeler.",
        "不会预先勾选。黑名单可能也涵盖曾经正当的软件的旧版本，社区报告也未经厂商确认，删除前请逐个核对。": "Hiçbir şey önceden seçilmez. Bir engelleme listesi, bir zamanlar güvenilir olan yazılımların eski sürümlerini de kapsayabilir ve topluluk bildirimleri hiçbir üretici tarafından doğrulanmaz; bu nedenle kaldırmadan önce her birini kontrol edin.",
        "正在比对 XProtect 和 MalwareBazaar 哈希值...": "XProtect ve MalwareBazaar karmaları karşılaştırılıyor...",
        "已报告至 MalwareBazaar：{name}": "MalwareBazaar'a bildirildi: {name}",
        "MalwareBazaar：未启用（可在设置中添加免费的 Auth-Key）": "MalwareBazaar: kapalı (Ayarlar'da ücretsiz bir Auth-Key ekleyin)",
